INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,61,'Al-Anbiyaa','قَالُواْ فَأۡتُواْ بِهِۦ عَلَىٰٓ أَعۡيُنِ ٱلنَّاسِ لَعَلَّهُمۡ يَشۡهَدُونَ','وہ بولے کہ اسے لوگوں کے سامنے لاؤ تاکہ گواہ رہیں','They demanded, “Bring him before the eyes of the people, so that they may witness ˹his trial˺.”','लोगों ने कहा तो अच्छा उसको सब लोगों के सामने (गिरफ्तार करके) ले आओ ताकि वह (जो कुछ कहें) लोग उसके गवाह रहें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,62,'Al-Anbiyaa','قَالُوٓاْ ءَأَنتَ فَعَلۡتَ هَٰذَا بِـَٔالِهَتِنَا يَٰٓإِبۡرَٰهِيمُ','(جب ابراہیم آئے تو) بت پرستوں نے کہا کہ ابراہیم بھلا یہ کام ہمارے معبودوں کے ساتھ تم نے کیا ہے؟','They asked, “Was it you who did this to our gods, O Abraham?”','(ग़रज़ इबराहीम आए) और लोगों ने उनसे पूछा कि क्यों इबराहीम क्या तुमने माबूदों के साथ ये हरकत की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,63,'Al-Anbiyaa','قَالَ بَلۡ فَعَلَهُۥ كَبِيرُهُمۡ هَٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُواْ يَنطِقُونَ','(ابراہیم نے) کہا (نہیں) بلکہ یہ ان کے اس بڑے (بت) نے کیا (ہوگا) ۔ اگر یہ بولتے ہیں تو ان سے پوچھ لو','He replied ˹sarcastically˺, “No, this one—the biggest of them—did it! So ask them, if they can talk!”','इबराहीम ने कहा बल्कि ये हरकत इन बुतों (खुदाओं) के बड़े (खुदा) ने की है तो अगर ये बुत बोल सकते हों तो उनही से पूछ देखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,64,'Al-Anbiyaa','فَرَجَعُوٓاْ إِلَىٰٓ أَنفُسِهِمۡ فَقَالُوٓاْ إِنَّكُمۡ أَنتُمُ ٱلظَّٰلِمُونَ','انہوں نے اپنے دل غور کیا تو آپس میں کہنے لگے بےشک تم ہی بےانصاف ہو','So they came back to their senses, saying ˹to one another˺, “You yourselves are truly the wrongdoers!”','इस पर उन लोगों ने अपने जी में सोचा तो (एक दूसरे से) कहने लगे बेशक तुम ही लोग खुद बर सरे नाहक़ हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,65,'Al-Anbiyaa','ثُمَّ نُكِسُواْ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَٰٓؤُلَآءِ يَنطِقُونَ','پھر (شرمندہ ہو کر) سر نیچا کرلیا (اس پر بھی ابراہیم سے کہنے لگے کہ) تم جانتے ہو یہ بولتے نہیں','Then they ˹quickly˺ regressed to their ˹original˺ mind-set, ˹arguing,˺ “You already know that those ˹idols˺ cannot talk.”','फिर उन लोगों के सर इसी गुमराही में झुका दिए गए (और तो कुछ बन न पड़ा मगर ये बोले) तुमको तो अच्छी तरह मालूम है कि ये बुत बोला नहीं करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,66,'Al-Anbiyaa','قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَنفَعُكُمۡ شَيۡـࣰٔ ا وَلَا يَضُرُّكُمۡ','(ابراہیم نے) کہا پھر تم خدا کو چھوڑ کر کیوں ایسی چیزوں کو پوجتے ہو جو نہ تمہیں کچھ فائدہ دے سکیں اور نقصان پہنچا سکیں؟','He rebuked ˹them˺, “Do you then worship—instead of Allah—what can neither benefit nor harm you in any way','(फिर इनसे क्या पूछे) इबराहीम ने कहा तो क्या तुम लोग खुदा को छोड़कर ऐसी चीज़ों की परसतिश करते हो जो न तुम्हें कुछ नफा ही पहुँचा सकती है और न तुम्हारा कुछ नुक़सान ही कर सकती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,67,'Al-Anbiyaa','أُفࣲّ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ','تف ہے تم پر اور جن کو تم خدا کے سوا پوجتے ہو ان پر بھی کیا تم عقل نہیں رکھتے؟','Shame on you and whatever you worship instead of Allah! Do you not have any sense?”','तफ है तुम पर उस चीज़ पर जिसे तुम खुदा के सिवा पूजते हो तो क्या तुम इतना भी नहीं समझते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,68,'Al-Anbiyaa','قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ','(تب وہ) کہنے لگے کہ اگر تمہیں (اس سے اپنے معبود کا انتقام لینا اور) کچھ کرنا ہے تو اس کو جلا دو اور اپنے معبودوں کی مدد کرو','They concluded, “Burn him up to avenge your gods, if you must act.”','(आख़िर) वह लोग (बाहम) कहने लगे कि अगर तुम कुछ कर सकते हो तो इबराहीम को आग में जला दो और अपने खुदाओं की मदद करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,69,'Al-Anbiyaa','قُلۡنَا يَٰنَارُ كُونِي بَرۡدࣰ ا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ','ہم نے حکم دیا اے آگ سرد ہوجا اور ابراہیم پر (موجب) سلامتی (بن جا)','We ordered, “O fire! Be cool and safe for Abraham!”','(ग़रज़) उन लोगों ने इबराहीम को आग में डाल दिया तो हमने फ़रमाया ऐ आग तू इबराहीम पर बिल्कुल ठन्डी और सलामती का बाइस हो जा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,70,'Al-Anbiyaa','وَأَرَادُواْ بِهِۦ كَيۡدࣰ ا فَجَعَلۡنَٰهُمُ ٱلۡأَخۡسَرِينَ','اور ان لوگوں نے برا تو ان کا چاہا تھا مگر ہم نے ان ہی کو نقصان میں ڈال دیا','They had sought to harm him, but We made them the worst losers','(कि उनको कोई तकलीफ़ न पहुँचे) और उन लोगों में इबराहीम के साथ चालबाज़ी करनी चाही थी तो हमने इन सब को नाकाम कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,71,'Al-Anbiyaa','وَنَجَّيۡنَٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَا لِلۡعَٰلَمِينَ','اور ابراہیم اور لوط کو اس سرزمین کی طرف بچا نکالا جس میں ہم نے اہل عالم کے لئے برکت رکھی تھی','Then We delivered him, along with Lot, to the land We had showered with blessings for all people','और हम ने ही इबराहीम और लूत को (सरकशों से) सही व सालिम निकालकर इस सर ज़मीन (शाम बैतुलमुक़द्दस) में जा पहुँचाया जिसमें हमने सारे जहाँन के लिए तरह-तरह की बरकत अता की थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,72,'Al-Anbiyaa','وَوَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَ نَافِلَةࣰۖ وَكُلࣰّ ا جَعَلۡنَا صَٰلِحِينَ','اور ہم نے ابراہیم کو اسحق عطا کئے۔ اور مستزاد برآں یعقوب۔ اور سب کو نیک بخت کیا','And We blessed him with Isaac ˹as a son˺ and Jacob ˹as a grandson˺, as an additional favour—making all of them righteous','और हमने इबराहीम को इनाम में इसहाक़ (जैसा बैटा) और याकूब (जैसा पोता) इनायत फरमाया हमने सबको नेक बख्त बनाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,73,'Al-Anbiyaa','وَجَعَلۡنَٰهُمۡ أَئِمَّةࣰ يَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَيۡنَآ إِلَيۡهِمۡ فِعۡلَ ٱلۡخَيۡرَٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِيتَآءَ ٱلزَّكَوٰةِۖ وَكَانُواْ لَنَا عَٰبِدِينَ','اور ان کو پیشوا بنایا کہ ہمارے حکم سے ہدایت کرتے تھے اور ان کو نیک کام کرنے اور نماز پڑھنے اور زکوٰة دینے کا حکم بھیجا۔ اور وہ ہماری عبادت کیا کرتے تھے','We ˹also˺ made them leaders, guiding by Our command, and inspired them to do good deeds, establish prayer, and pay alms-tax. And they were devoted to Our worship','और उन सबको (लोगों का) पेशवा बनाया कि हमारे हुक्म से (उनकी) हिदायत करते थे और हमने उनके पास नेक काम करने और नमाज़ पढ़ने और ज़कात देने की ''''वही'''' भेजी थी और ये सब के सब हमारी ही इबादत करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,74,'Al-Anbiyaa','وَلُوطًا ءَاتَيۡنَٰهُ حُكۡمࣰ ا وَعِلۡمࣰ ا وَنَجَّيۡنَٰهُ مِنَ ٱلۡقَرۡيَةِ ٱلَّتِي كَانَت تَّعۡمَلُ ٱلۡخَبَٰٓئِثَۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءࣲ فَٰسِقِينَ','اور لوط (کا قصہ یاد کرو) جب ان کو ہم نے حکم (یعنی حکمت ونبوت) اور علم بخشا اور اس بستی سے جہاں کے لوگ گندے کام کیا کرتے تھے۔ بچا نکالا۔ بےشک وہ برے اور بدکردار لوگ تھے','And to Lot We gave wisdom and knowledge, and delivered him from the society engrossed in shameful practices. They were certainly an evil, rebellious people','और लूत को भी हम ही के फ़हमे सलीम और नबूवत अता की और हम ही ने उस बस्ती से जहाँ के लोग बदकारियाँ करते थे नजात दी इसमें शक नहीं कि वह लोग बड़े बदकार आदमी थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,75,'Al-Anbiyaa','وَأَدۡخَلۡنَٰهُ فِي رَحۡمَتِنَآۖ إِنَّهُۥ مِنَ ٱلصَّٰلِحِينَ','اور انہیں اپنی رحمت کے (محل میں) داخل کیا۔ کچھ شک نہیں کہ وہ نیک بختوں میں تھے','And We admitted him into Our mercy, ˹for˺ he was truly one of the righteous','और हमने लूत को अपनी रहमत में दाख़िल कर लिया इसमें शक नहीं कि वह नेकोंकार बन्दों में से थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,76,'Al-Anbiyaa','وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ','اور نوح (کا قصہ بھی یاد کرو) جب (اس سے) پیشتر انہوں نے ہم کو پکارا تو ہم نے ان کی دعا قبول فرمائی اور ان کو اور ان کے ساتھیوں کو بڑی گھبراہٹ سے نجات دی','And ˹remember˺ when Noah had cried out to Us earlier, so We responded to him and delivered him and his family from the great distress','और (ऐ रसूल लूत से भी) पहले (हमने) नूह को नबूवत पर फ़ायज़ किया जब उन्होंने (हमको) आवाज़ दी तो हमने उनकी (दुआ) सुन ली फिर उनको और उनके साथियों को (तूफ़ान की) बड़ी सख्त मुसीबत से नजात दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,77,'Al-Anbiyaa','وَنَصَرۡنَٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمَ سَوۡءࣲ فَأَغۡرَقۡنَٰهُمۡ أَجۡمَعِينَ','اور جو لوگ ہماری آیتوں کی تکذیب کرتے تھے ان پر نصرت بخشی۔ وہ بےشک برے لوگ تھے سو ہم نے ان سب کو غرق کردیا','And We made him prevail over those who had rejected Our signs. They were truly an evil people, so We drowned them all','और जिन लोगों ने हमारी आयतों को झुठलाया था उनके मुक़ाबले में उनकी मदद की बेशक ये लोग (भी) बहुत बुरे लोग थे तो हमने उन सबको डुबो मारा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,78,'Al-Anbiyaa','وَدَاوُۥدَ وَسُلَيۡمَٰنَ إِذۡ يَحۡكُمَانِ فِي ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِيهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَٰهِدِينَ','اور داؤد اور سلیمان (کا حال بھی سن لو کہ) جب وہ ایک کھیتی کا مقدمہ فیصلہ کرنے لگے جس میں کچھ لوگوں کی بکریاں رات کو چر گئی (اور اسے روند گئی) تھیں اور ہم ان کے فیصلے کے وقت موجود تھے','And ˹remember˺ when David and Solomon passed judgment regarding the crops ruined ˹at night˺ by someone’s sheep, and We were witness to their judgments','और (ऐ रसूल इनको) दाऊद और सुलेमान का (वाक्या याद दिलाओ) जब ये दोनों एक खेती के बारे में जिसमें रात के वक्त क़ुछ लोगों की बकरियाँ (घुसकर) चर गई थी फैसला करने बैठे और हम उन लोगों के क़िस्से को देख रहे थे (कि बाहम इख़तेलाफ़ हुआ)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,79,'Al-Anbiyaa','فَفَهَّمۡنَٰهَا سُلَيۡمَٰنَۚ وَكُلًّا ءَاتَيۡنَا حُكۡمࣰ ا وَعِلۡمࣰ اۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ يُسَبِّحۡنَ وَٱلطَّيۡرَۚ وَكُنَّا فَٰعِلِينَ','تو ہم نے فیصلہ (کرنے کا طریق) سلیمان کو سمجھا دیا۔ اور ہم نے دونوں کو حکم (یعنی حکمت ونبوت) اور علم بخشا تھا۔ اور ہم نے پہاڑوں کو داؤد کا مسخر کردیا تھا کہ ان کے ساتھ تسبیح کرتے تھے اور جانوروں کو بھی (مسخر کردیا تھا اور ہم ہی ایسا) کرنے والے تھے','We guided ˹young˺ Solomon to a fairer settlement, and granted each of them wisdom and knowledge. We subjected the mountains as well as the birds to hymn ˹Our praises˺ along with David. It is We Who did ˹it all˺','तो हमने सुलेमान को (इसका सही फ़ैसला समझा दिया) और (यूँ तो) सबको हम ही ने फहमे सलीम और इल्म अता किया और हम ही ने पहाड़ों को दाऊद का ताबेए बना दिया था कि उनके साथ (खुदा की) तस्बीह किया करते थे और परिन्दों को (भी ताबेए कर दिया था) और हम ही (ये अज़ाब) किया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,80,'Al-Anbiyaa','وَعَلَّمۡنَٰهُ صَنۡعَةَ لَبُوسࣲ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَٰكِرُونَ','اور ہم نے تمہارے لئے ان کو ایک (طرح) کا لباس بنانا بھی سکھا دیا تاکہ تم کو لڑائی (کے ضرر) سے بچائے۔ پس تم کو شکرگزار ہونا چاہیئے','We taught him the art of making body armour to protect you in battle. Will you then be grateful','और हम ही ने उनको तुम्हारी जंगी पोशिश (ज़िराह) का बनाना सिखा दिया ताकि तुम्हें (एक दूसरे के) वार से बचाए तो क्या तुम (अब भी) उसके शुक्रगुज़ार बनोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,81,'Al-Anbiyaa','وَلِسُلَيۡمَٰنَ ٱلرِّيحَ عَاصِفَةࣰ تَجۡرِي بِأَمۡرِهِۦٓ إِلَى ٱلۡأَرۡضِ ٱلَّتِي بَٰرَكۡنَا فِيهَاۚ وَكُنَّا بِكُلِّ شَيۡءٍ عَٰلِمِينَ','اور ہم نے تیز ہوا سلیمان کے تابع (فرمان) کردی تھی جو ان کے حکم سے اس ملک میں چلتی تھی جس میں ہم نے برکت دی تھی (یعنی شام) اور ہم ہر چیز سے خبردار ہیں','And to Solomon We subjected the raging winds, blowing by his command to the land We had showered with blessings. It is We Who know everything','और (हम ही ने) बड़े ज़ोरों की हवा को सुलेमान का (ताबेए कर दिया था) कि वह उनके हुक्म से इस सरज़मीन (बैतुलमुक़द्दस) की तरफ चला करती थी जिसमें हमने तरह-तरह की बरकतें अता की थी और हम तो हर चीज़ से खूब वाक़िफ़ थे (और) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,82,'Al-Anbiyaa','وَمِنَ ٱلشَّيَٰطِينِ مَن يَغُوصُونَ لَهُۥ وَيَعۡمَلُونَ عَمَلࣰ ا دُونَ ذَٰلِكَۖ وَكُنَّا لَهُمۡ حَٰفِظِينَ','اور دیوؤں (کی جماعت کو بھی ان کے تابع کردیا تھا کہ ان) میں سے بعض ان کے لئے غوطے مارتے تھے اور اس کے سوا اور کام بھی کرتے تھے اور ہم ان کے نگہبان تھے','And ˹We subjected˺ some jinn that dived for him, and performed other duties. It is We Who kept them in check','और जिन्नात में से जो लोग (समन्दर में) ग़ोता लगाकर (जवाहरात निकालने वाले) थे और उसके अलावा और काम भी करते थे (सुलेमान का ताबेए कर दिया था) और हम ही उनके निगेहबान थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,83,'Al-Anbiyaa','۞وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ','اور ایوب کو (یاد کرو) جب انہوں نے اپنے پروردگار سے دعا کی کہ مجھے ایذا ہو رہی ہے اور تو سب سے بڑھ کر رحم کرنے والا ہے','And ˹remember˺ when Job cried out to his Lord, “I have been touched with adversity, and You are the Most Merciful of the merciful.”','(कि भाग न जाएँ) और (ऐ रसूल) अय्यूब (का क़िस्सा याद करो) जब उन्होंने अपने परवरदिगार से दुआ की कि (ख़ुदा वन्द) बीमारी तो मेरे पीछे लग गई है और तू तो सब रहम करने वालोंसे (बढ़ कर है मुझ पर तरस खा)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,84,'Al-Anbiyaa','فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرࣲّۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ','تو ہم نے ان کی دعا قبول کرلی اور جو ان کو تکلیف تھی وہ دور کردی اور ان کو بال بچے بھی عطا فرمائے اور اپنی مہربانی کے ساتھ اتنے ہی اور (بخشے) اور عبادت کرنے والوں کے لئے (یہ) نصیحت ہے','So We answered his prayer and removed his adversity, and gave him back his family, twice as many, as a mercy from Us and a lesson for the ˹devoted˺ worshippers','तो हमने उनकी दुआ कुबूल की तो हमने उनका जो कुछ दर्द दुख था दफ़ा कर दिया और उन्हें उनके लड़के वाले बल्कि उनके साथ उतनी ही और भी महज़ अपनी ख़ास मेहरबानी से और इबादत करने वालों की इबरत के वास्ते अता किए');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,85,'Al-Anbiyaa','وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّٰبِرِينَ','اور اسمٰعیل اور ادریس اور ذوالکفل (کو بھی یاد کرو) یہ سب صبر کرنے والے تھے','And ˹remember˺ Ishmael, Enoch, and Ⱬul-Kifl. They were all steadfast','और (ऐ रसूल) इसमाईल और इदरीस और जुलकिफ्ल (के वाक़यात से याद करो) ये सब साबिर बन्दे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,86,'Al-Anbiyaa','وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ','اور ہم نے ان کو اپنی رحمت میں داخل کیا۔ بلاشبہ وہ نیکوکار تھے','We admitted them into Our mercy, for they were truly of the righteous','और हमने उन सबको अपनी (ख़ास) रहमत में दाख़िल कर लिया बेशक ये लोग नेक बन्दे थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,87,'Al-Anbiyaa','وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبࣰ ا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ','اور ذوالنون (کو یاد کرو) جب وہ (اپنی قوم سے ناراض ہو کر) غصے کی حالت میں چل دیئے اور خیال کیا کہ ہم ان پر قابو نہیں پاسکیں گے۔ آخر اندھیرے میں (خدا کو) پکارنے لگے کہ تیرے سوا کوئی معبود نہیں۔ تو پاک ہے (اور) بےشک میں قصوروار ہوں','And ˹remember˺ when the Man of the Whale stormed off ˹from his city˺ in a rage, thinking We would not restrain him. Then in the ˹veils of˺ darkness he cried out, “There is no god ˹worthy of worship˺ except You. Glory be to You! I have certainly done wrong.”','और जुन्नून (यूनुस को याद करो) जबकि गुस्से में आकर चलते हुए और ये ख्याल न किया कि हम उन पर रोज़ी तंग न करेंगे (तो हमने उन्हें मछली के पेट में पहुँचा दिया) तो (घटाटोप) अंधेरे में (घबराकर) चिल्ला उठा कि (परवरदिगार) तेरे सिवा कोई माबूद नहीं तू (हर ऐब से) पाक व पाकीज़ा है बेशक मैं कुसूरवार हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,88,'Al-Anbiyaa','فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ','تو ہم نے ان کی دعا قبول کرلی اور ان کو غم سے نجات بخشی۔ اور ایمان والوں کو ہم اسی طرح نجات دیا کرتے ہیں','So We answered his prayer and rescued him from anguish. And so do We save the ˹true˺ believers','तो हमने उनकी दुआ कुबूल की और उन्हें रंज से नजात दी और हम तो ईमानवालों को यूँ ही नजात दिया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,89,'Al-Anbiyaa','وَزَكَرِيَّآ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِي فَرۡدࣰ ا وَأَنتَ خَيۡرُ ٱلۡوَٰرِثِينَ','اور زکریا (کو یاد کرو) جب انہوں نے اپنے پروردگار کو پکارا کہ پروردگار مجھے اکیلا نہ چھوڑ اور تو سب سے بہتر وارث ہے','And ˹remember˺ when Zachariah cried out to his Lord, “My Lord! Do not leave me childless, though You are the Best of Successors.”','और ज़करिया (को याद करो) जब उन्होंने (मायूस की हालत में) अपने परवरदिगार से दुआ की ऐ मेरे पालने वाले मुझे तन्हा (बे औलाद) न छोड़ और तू तो सब वारिसों से बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,90,'Al-Anbiyaa','فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبࣰ ا وَرَهَبࣰ اۖ وَكَانُواْ لَنَا خَٰشِعِينَ','تو ہم نے ان کی پکار سن لی۔ اور ان کو یحییٰ بخشے اور ان کی بیوی کو اُن کے (حسن معاشرت کے) قابل بنادیا۔ یہ لوگ لپک لپک کر نیکیاں کرتے اور ہمیں امید سے پکارتے اور ہمارے آگے عاجزی کیا کرتے تھے','So We answered his prayer, granted him John, and made his wife fertile. Indeed, they used to race in doing good, and call upon Us with hope and fear, totally humbling themselves before Us','तो हमने उनकी दुआ सुन ली और उन्हें यहया सा बेटा अता किया और हमने उनके लिए उनकी बीबी को अच्छी बता दिया इसमें शक नहीं कि ये सब नेक कामों में जल्दी करते थे और हमको बड़ी रग़बत और ख़ौफ के साथ पुकारा करते थे और हमारे आगे गिड़गिड़ाया करते थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,91,'Al-Anbiyaa','وَٱلَّتِيٓ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِيهَا مِن رُّوحِنَا وَجَعَلۡنَٰهَا وَٱبۡنَهَآ ءَايَةࣰ لِّلۡعَٰلَمِينَ','اور ان (مریم) کو (بھی یاد کرو) جنہوں نے اپنی عفّت کو محفوظ رکھا۔ تو ہم نے ان میں اپنی روح پھونک دی اور ان کے بیٹے کو اہل عالم کے لئے نشانی بنا دیا','And ˹remember˺ the one who guarded her chastity, so We breathed into her through Our angel, ˹Gabriel,˺ making her and her son a sign for all peoples','और (ऐ रसूल) उस बीबी को (याद करो) जिसने अपनी अज़मत की हिफाज़त की तो हमने उन (के पेट) में अपनी तरफ से रूह फूँक दी और उनको और उनके बेटे (ईसा) को सारे जहाँन के वास्ते (अपनी क़ुदरत की) निशानी बनाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,92,'Al-Anbiyaa','إِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ','یہ تمہاری جماعت ایک ہی جماعت ہے اور میں تمہارا پروردگار ہوں تو میری ہی عبادت کیا کرو','˹O prophets!˺ Indeed, this religion of yours is ˹only˺ one, and I am your Lord, so worship Me ˹alone˺','बेशक ये तुम्हारा दीन (इस्लाम) एक ही दीन है और मैं तुम्हारा परवरदिगार हूँ तो मेरी ही इबादत करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,93,'Al-Anbiyaa','وَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡۖ كُلٌّ إِلَيۡنَا رَٰجِعُونَ','اور یہ لوگ اپنے معاملے میں باہم متفرق ہوگئے۔ (مگر) سب ہماری طرف رجوع کرنے والے ہیں','Yet the people have divided it into sects. But to Us they will all return','और लोगों ने बाहम (इख़तेलाफ़ करके) अपने दीन को टुकड़े -टुकड़े कर डाला (हालाँकि) वह सब के सब हिरफिर के हमारे ही पास आने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,94,'Al-Anbiyaa','فَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا كُفۡرَانَ لِسَعۡيِهِۦ وَإِنَّا لَهُۥ كَٰتِبُونَ','جو نیک کام کرے گا اور مومن بھی ہوگا تو اس کی کوشش رائیگاں نہ جائے گی۔ اور ہم اس کے لئے (ثواب اعمال) لکھ رہے ہیں','So whoever does good and is a believer will never be denied ˹the reward for˺ their striving, for We are recording it all','(उस वक्त फ़ैसला हो जाएगा कि) तो जो शख्स अच्छे-अच्छे काम करेगा और वह ईमानवाला भी हो तो उसकी कोशिश अकारत न की जाएगी और हम उसके आमाल लिखते जाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,95,'Al-Anbiyaa','وَحَرَٰمٌ عَلَىٰ قَرۡيَةٍ أَهۡلَكۡنَٰهَآ أَنَّهُمۡ لَا يَرۡجِعُونَ','اور جس بستی (والوں) کو ہم نے ہلاک کردیا محال ہے کہ (وہ دنیا کی طرف رجوع کریں) وہ رجوع نہیں کریں گے','It is impossible for a society which We have destroyed to ever rise again','और जिस बस्ती को हमने तबाह कर डाला मुमकिन नहीं कि वह लोग क़यामत के दिन हिरफिर के से (हमारे पास) न लौटे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,96,'Al-Anbiyaa','حَتَّىٰٓ إِذَا فُتِحَتۡ يَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبࣲ يَنسِلُونَ','یہاں تک کہ یاجوج ماجوج کھول دیئے جائیں اور وہ ہر بلندی سے دوڑ رہے ہوں','until ˹after˺ Gog and Magog have broken loose ˹from the barrier˺, swarming down from every hill','बस इतना (तवक्कुफ़ तो ज़रूर होगा) कि जब याजूज माजूज (सद्दे सिकन्दरी) की कैद से खोल दिए जाएँगे और ये लोग (ज़मीन की) हर बुलन्दी से दौड़ते हुए निकल पड़े');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,97,'Al-Anbiyaa','وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِيَ شَٰخِصَةٌ أَبۡصَٰرُ ٱلَّذِينَ كَفَرُواْ يَٰوَيۡلَنَا قَدۡ كُنَّا فِي غَفۡلَةࣲ مِّنۡ هَٰذَا بَلۡ كُنَّا ظَٰلِمِينَ','اور (قیامت کا) سچا وعدہ قریب آجائے تو ناگاہ کافروں کی آنکھیں کھلی کی کھلی رہ جائیں (اور کہنے لگیں کہ) ہائے شامت ہم اس (حال) سے غفلت میں رہے بلکہ (اپنے حق میں) ظالم تھے','ushering in the True Promise. Then—behold!—the disbelievers will stare ˹in horror, crying,˺ “Oh, woe to us! We have truly been heedless of this. In fact, we have been wrongdoers.”','और क़यामत का सच्चा वायदा नज़दीक आ जाए तो फिर काफिरों की ऑंखें एक दम से पथरा दी जाएँ (और कहने लगे) हाय हमारी शामत कि हम तो इस (दिन) से ग़फलत ही में (पड़े) रहे बल्कि (सच तो यूँ है कि अपने ऊपर) हम आप ज़ालिम थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,98,'Al-Anbiyaa','إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَٰرِدُونَ','(کافرو اس روز) تم اور جن کی تم خدا کے سوا عبادت کرتے ہو دوزخ کا ایندھن ہوں گے۔ اور تم سب اس میں داخل ہو کر رہو گے','Certainly you ˹disbelievers˺ and whatever you worship instead of Allah will be the fuel of Hell. You are ˹all˺ bound to enter it','(उस दिन किहा जाएगा कि ऐ कुफ्फ़ार) तुम और जिस चीज़ की तुम खुदा के सिवा परसतिश करते थे यक़ीनन जहन्नुम की ईधन (जलावन) होंगे (और) तुम सबको उसमें उतरना पड़ेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,99,'Al-Anbiyaa','لَوۡ كَانَ هَٰٓؤُلَآءِ ءَالِهَةࣰ مَّا وَرَدُوهَاۖ وَكُلࣱّ فِيهَا خَٰلِدُونَ','اگر یہ لوگ (درحقیقت) معبود ہوتے تو اس میں داخل نہ ہوتے۔ سب اس میں ہمیشہ (جلتے) رہیں گے','Had those idols been ˹true˺ gods, they would not have entered it. And they will be there forever','अगर ये (सच्चे) माबूद होते तो उन्हें दोज़ख़ में न जाना पड़ता और (अब तो) सबके सब उसी में हमेशा रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,100,'Al-Anbiyaa','لَهُمۡ فِيهَا زَفِيرࣱ وَهُمۡ فِيهَا لَا يَسۡمَعُونَ','وہاں ان کو چلاّنا ہوگا اور اس میں (کچھ) نہ سن سکیں گے','In it they will groan, and will not be able to hear','उन लोगों की दोज़ख़ में चिंघाड़ होगी और ये लोग (अपने शोर व ग़ुल में) किसी की बात भी न सुन सकेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,101,'Al-Anbiyaa','إِنَّ ٱلَّذِينَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰٓ أُوْلَٰٓئِكَ عَنۡهَا مُبۡعَدُونَ','جن لوگوں کے لئے ہماری طرف سے پہلے بھلائی مقرر ہوچکی ہے۔ وہ اس سے دور رکھے جائیں گے','Surely those for whom We have destined the finest reward will be kept far away from Hell','ज़बान अलबत्ता जिन लोगों के वास्ते हमारी तरफ से पहले ही भलाई (तक़दीर में लिखी जा चुकी) वह लोग दोज़ख़ से दूर ही दूर रखे जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,102,'Al-Anbiyaa','لَا يَسۡمَعُونَ حَسِيسَهَاۖ وَهُمۡ فِي مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَٰلِدُونَ','(یہاں تک کہ) اس کی آواز بھی تو نہیں سنیں گے۔ اور جو کچھ ان کا جی چاہے گا اس میں (یعنی) ہر طرح کے عیش اور لطف میں ہمیشہ رہیں گے','not even hearing the slightest hissing from it. And they will delight forever in what their souls desire','(यहाँ तक) कि ये लोग उसकी भनक भी न सुनेंगे और ये लोग हमेशा अपनी मनमाँगी मुरादों में (चैन से) रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,103,'Al-Anbiyaa','لَا يَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ هَٰذَا يَوۡمُكُمُ ٱلَّذِي كُنتُمۡ تُوعَدُونَ','ان کو (اس دن کا) بڑا بھاری خوف غمگین نہیں کرے گا۔ اور فرشتے ان کو لینے آئیں گے (اور کہیں گے کہ) یہی وہ دن ہے جس کا تم سے وعدہ کیا جاتا ہے','The Supreme Horror ˹of that Day˺ will not disturb them, and the angels will greet them, ˹saying,˺ “This is your Day, which you have been promised.”','और उनको (क़यामत का) बड़े से बड़ा ख़ौफ़ भी दहशत में न लाएगा और फ़रिश्ते उन से खुशी-खुशी मुलाक़ात करेंगे और ये खुशख़बरी देंगे कि यही वह तुम्हारा (खुशी का) दिन है जिसका (दुनिया में) तुमसे वायदा किया जाता था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,104,'Al-Anbiyaa','يَوۡمَ نَطۡوِي ٱلسَّمَآءَ كَطَيِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَآ أَوَّلَ خَلۡقࣲ نُّعِيدُهُۥۚ وَعۡدًا عَلَيۡنَآۚ إِنَّا كُنَّا فَٰعِلِينَ','جس دن ہم آسمان کو اس طرح لپیٹ لیں گے جیسے خطوں کا طومار لپیٹ لیتے ہیں۔ جس طرح ہم نے (کائنات کو) پہلے پیدا کیا اسی طرح دوبارہ پیدا کردیں گے۔ (یہ) وعدہ (جس کا پورا کرنا لازم) ہے۔ ہم (ایسا) ضرور کرنے والے ہیں','On that Day We will roll up the heavens like a scroll of writings. Just as We produced the first creation, ˹so˺ shall We reproduce it. That is a promise binding on Us. We truly uphold ˹Our promises˺','(ये) वह दिन (होगा) जब हम आसमान को इस तरह लपेटेगे जिस तरह ख़तों का तूमार लपेटा जाता है जिस तरह हमने (मख़लूक़ात को) पहली बार पैदा किया था (उसी तरह) दोबारा (पैदा) कर छोड़ेगें (ये वह) वायदा (है जिसका करना) हम पर (लाज़िम) है और हम उसे ज़रूर करके रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,105,'Al-Anbiyaa','وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ يَرِثُهَا عِبَادِيَ ٱلصَّٰلِحُونَ','اور ہم نے نصیحت (کی کتاب یعنی تورات) کے بعد زبور میں لکھ دیا تھا کہ میرے نیکوکار بندے ملک کے وارث ہوں گے','Surely, following the ˹heavenly˺ Record, We decreed in the Scriptures: “My righteous servants shall inherit the land.”','और हमने तो नसीहत (तौरेत) के बाद यक़ीनन जुबूर में लिख ही दिया था कि रूए ज़मीन के वारिस हमारे नेक बन्दे होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,106,'Al-Anbiyaa','إِنَّ فِي هَٰذَا لَبَلَٰغࣰ ا لِّقَوۡمٍ عَٰبِدِينَ','عبادت کرنے والے لوگوں کے لئے اس میں (خدا کے حکموں کی) تبلیغ ہے','Surely this ˹Quran˺ is sufficient ˹as a reminder˺ for those devoted to worship','इसमें शक नहीं कि इसमें इबादत करने वालों के लिए (एहकामें खुदा की) तबलीग़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,107,'Al-Anbiyaa','وَمَآ أَرۡسَلۡنَٰكَ إِلَّا رَحۡمَةࣰ لِّلۡعَٰلَمِينَ','اور (اے محمدﷺ) ہم نے تم کو تمام جہان کے لئے رحمت (بنا کر) بھیجا ہے','We have sent you ˹O Prophet˺ only as a mercy for the whole world','और (ऐ रसूल) हमने तो तुमको सारे दुनिया जहाँन के लोगों के हक़ में अज़सरतापा रहमत बनाकर भेजा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,108,'Al-Anbiyaa','قُلۡ إِنَّمَا يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ','کہہ دو کہ مجھ پر (خدا کی طرف سے) یہ وحی آتی ہے کہ تم سب کا معبود خدائے واحد ہے۔ تو تم کو چاہیئے کہ فرمانبردار بن جاؤ','Say, “What has been revealed to me is this: ‘Your God is only One God.’ Will you then submit?”','तुम कह दो कि मेरे पास तो बस यही ''''वही'''' आई है कि तुम लोगों का माबूद बस यकता खुदा है तो क्या तुम (उसके) फरमाबरदार बन्दे बनते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,109,'Al-Anbiyaa','فَإِن تَوَلَّوۡاْ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَآءࣲۖ وَإِنۡ أَدۡرِيٓ أَقَرِيبٌ أَم بَعِيدࣱ مَّا تُوعَدُونَ','اگر یہ لوگ منہ پھیریں تو کہہ دو کہ میں نے تم کو سب کو یکساں (احکام الہیٰ سے) آگاہ کردیا ہے۔ اور مجھ کو معلوم نہیں کہ جس چیز کا تم سے وعدہ کیا جاتا ہے وہ (عن) قریب (آنے والی) ہے یا (اس کا وقت) دور ہے','If they turn away, then say, “I have warned you all equally. I do not know if what you are threatened with is near or far','फिर अगर ये लोग (उस पर भी) मुँह फेरें तो तुम कह दो कि मैंने तुम सबको यकसाँ ख़बर कर दी है और मैं नहीं जानता कि जिस (अज़ाब) का तुमसे वायदा किया गया है क़रीब आ पहुँचा या (अभी) दूर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,110,'Al-Anbiyaa','إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَيَعۡلَمُ مَا تَكۡتُمُونَ','اور جو بات پکار کی جائے وہ اسے بھی جانتا ہے اور جو تم پوشیدہ کرتے ہو اس سے بھی واقف ہے','Allah surely knows what you say openly and whatever you hide','इसमें शक नहीं कि वह उस बात को भी जानता है जो पुकार कर कही जाती है और जिसे तुम लोग छिपाते हो उससे भी खूब वाक़िफ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,111,'Al-Anbiyaa','وَإِنۡ أَدۡرِي لَعَلَّهُۥ فِتۡنَةࣱ لَّكُمۡ وَمَتَٰعٌ إِلَىٰ حِينࣲ‏','اور میں نہیں جانتا شاید وہ تمہارے لئے آزمائش ہو اور ایک مدت تک (تم اس سے) فائدہ (اٹھاتے رہو)','I do not know if this ˹delay˺ is possibly a test for you and an enjoyment for a while.”','और मैं ये भी नहीं जानता कि शायद ये (ताख़ीरे अज़ाब तुम्हारे) वास्ते इम्तिहान हो और एक मुअय्युन मुद्दत तक (तुम्हारे लिए) चैन हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (21,112,'Al-Anbiyaa','قَٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ','پیغمبر نے کہا کہ اے میرے پروردگار حق کے ساتھ فیصلہ کردے۔ اور ہمارا پروردگار بڑا مہربان ہے اسی سے ان باتوں میں جو تم بیان کرتے ہو مدد مانگی جاتی ہے','˹In the end,˺ the Prophet said, “My Lord! Judge ˹between us˺ in truth. And our Lord is the Most Compassionate, Whose help is sought against what you claim.”','(आख़िर) रसूल ने दुआ की ऐ मेरे पालने वाले तू ठीक-ठीक मेरे और काफिरों के दरमियान फैसला कर दे और हमार परवरदिगार बड़ा मेहरबान है कि उसी से इन बातों में मदद माँगी जाती है जो तुम लोग बयान करते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,1,'Al-Hajj','يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَيۡءٌ عَظِيمࣱ‏','لوگو! اپنے پروردگار سے ڈرو۔ کہ قیامت کا زلزلہ ایک حادثہٴ عظیم ہوگا','O humanity! Fear your Lord, for the ˹violent˺ quaking at the Hour is surely a dreadful thing','ऐ लोगों अपने परवरदिगार से डरते रहो (क्योंकि) क़यामत का ज़लज़ला (कोई मामूली नहीं) एक बड़ी (सख्त) चीज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,2,'Al-Hajj','يَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّآ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدࣱ‏','(اے مخاطب) جس دن تو اس کو دیکھے گا (اُس دن یہ حال ہوگا کہ) تمام دودھ پلانے والی عورتیں اپنے بچوں کو بھول جائیں گی۔ اور تمام حمل والیوں کے حمل گر پڑیں گے۔ اور لوگ تجھ کو متوالے نظر آئیں گے مگر وہ متوالے نہیں ہوں گے بلکہ (عذاب دیکھ کر) مدہوش ہو رہے ہوں گے۔ بےشک خدا کا عذاب بڑا سخت ہے','The Day you see it, every nursing mother will abandon what she is nursing, and every pregnant woman will deliver her burden ˹prematurely˺. And you will see people ˹as if they were˺ drunk, though they will not be drunk; but the torment of Allah is ˹terribly˺ severe','जिस दिन तुम उसे देख लोगे तो हर दूध पिलाने वाली (डर के मारे) अपने दूध पीते (बच्चे) को भूल जायेगी और सारी हामला औरते अपने-अपने हमल (बेहिश्त से) गिरा देगी और (घबराहट में) लोग तुझे मतवाले मालूम होंगे हालाँकि वह मतवाले नहीं हैं बल्कि खुदा का अज़ाब बहुत सख्त है कि लोग बदहवास हो रहे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,3,'Al-Hajj','وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَيَتَّبِعُ كُلَّ شَيۡطَٰنࣲ مَّرِيدࣲ‏','اور بعض لوگ ایسے ہیں جو خدا (کی شان) میں علم (ودانش) کے بغیر جھگڑتے اور ہر شیطان سرکش کی پیروی کرتے ہیں','˹Still˺ there are some who dispute about Allah without knowledge, and follow every rebellious devil','और कुछ लोग ऐसे भी हैं जो बग़ैर जाने खुदा के बारे में (ख्वाह म ख्वाह) झगड़ते हैं और हर सरकश शैतान के पीछे हो लेते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,4,'Al-Hajj','كُتِبَ عَلَيۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ يُضِلُّهُۥ وَيَهۡدِيهِ إِلَىٰ عَذَابِ ٱلسَّعِيرِ','جس کے بارے میں لکھ دیا گیا ہے کہ جو اسے دوست رکھے گا تو اس کو گمراہ کردے گا اور دوزخ کے عذاب کا رستہ دکھائے گا','It has been decreed for such devils that whoever takes them as a guide will be misguided and led by them into the torment of the Blaze','जिन (की पेशानी) के ऊपर (ख़ते तक़दीर से) लिखा जा चुका है कि जिसने उससे दोस्ती की हो तो ये यक़ीनन उसे गुमराह करके छोड़ेगा और दोज़ख़ के अज़ाब तक पहुँचा देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,5,'Al-Hajj','يَٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِي رَيۡبࣲ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَٰكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ مِن مُّضۡغَةࣲ مُّخَلَّقَةࣲ وَغَيۡرِ مُخَلَّقَةࣲ لِّنُبَيِّنَ لَكُمۡۚ وَنُقِرُّ فِي ٱلۡأَرۡحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّ ى ثُمَّ نُخۡرِجُكُمۡ طِفۡلࣰ ا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡلَا يَعۡلَمَ مِنۢ بَعۡدِ عِلۡمࣲ شَيۡـࣰٔ اۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةࣰ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِيجࣲ‏','لوگو اگر تم کو مرنے کے بعد جی اُٹھنے میں کچھ شک ہو تو ہم نے تم کو (پہلی بار بھی تو) پیدا کیا تھا (یعنی ابتدا میں) مٹی سے پھر اس سے نطفہ بنا کر۔ پھر اس سے خون کا لوتھڑا بنا کر۔ پھر اس سے بوٹی بنا کر جس کی بناوٹ کامل بھی ہوتی ہے اور ناقص بھی تاکہ تم پر (اپنی خالقیت) ظاہر کردیں۔ اور ہم جس کو چاہتے ہیں ایک میعاد مقرر تک پیٹ میں ٹھہرائے رکھتے ہیں پھر تم کو بچہ بنا کر نکالتے ہیں۔ پھر تم جوانی کو پہنچتے ہو۔ اور بعض (قبل از پیری مرجاتے ہیں اور بعض شیخ فالی ہوجاتے اور بڑھاپے کی) نہایت خراب عمر کی طرف لوٹائے جاتے ہیں کہ بہت کچھ جاننے کے بعد بالکل بےعلم ہوجاتے ہیں۔ اور (اے دیکھنے والے) تو دیکھتا ہے (کہ ایک وقت میں) زمین خشک (پڑی ہوتی ہے) پھر جب ہم اس پر مینہ برساتے ہیں تو شاداب ہوجاتی اور ابھرنے لگتی ہے اور طرح طرح کی بارونق چیزیں اُگاتی ہے','O humanity! If you are in doubt about the Resurrection, then ˹know that˺ We did create you from dust, then from a sperm-drop, then ˹developed you into˺ a clinging clot ˹of blood˺, then a lump of flesh—fully formed or unformed—in order to demonstrate ˹Our power˺ to you. ˹Then˺ We settle whatever ˹embryo˺ We will in the womb for an appointed term, then bring you forth as infants, so that you may reach your prime. Some of you ˹may˺ die ˹young˺, while others are left to reach the most feeble stage of life so that they may know nothing after having known much. And you see the earth lifeless, but as soon as We send down rain upon it, it begins to stir ˹to life˺ and swell, producing every type of pleasant plant','लोगों अगर तुमको (मरने के बाद) दोबारा जी उठने में किसी तरह का शक है तो इसमें शक नहीं कि हमने तुम्हें शुरू-शुरू मिट्टी से उसके बाद नुत्फे से उसके बाद जमे हुए ख़ून से फिर उस लोथड़े से जो पूरा (सूडौल हो) या अधूरा हो पैदा किया ताकि तुम पर (अपनी कुदरत) ज़ाहिर करें (फिर तुम्हारा दोबारा ज़िन्दा) करना क्या मुश्किल है और हम औरतों के पेट में जिस (नुत्फे) को चाहते हैं एक मुद्दत मुअय्यन तक ठहरा रखते हैं फिर तुमको बच्चा बनाकर निकालते हैं फिर (तुम्हें पालते हैं) ताकि तुम अपनी जवानी को पहुँचो और तुममें से कुछ लोग तो ऐसे हैं जो (क़ब्ल बुढ़ापे के) मर जाते हैं और तुम में से कुछ लोग ऐसे हैं जो नाकारा ज़िन्दगी बुढ़ापे तक फेर लाए हैं जातें ताकि समझने के बाद सठिया के कुछ भी (ख़ाक) न समझ सके और तो ज़मीन को मुर्दा (बेकार उफ़तादा) देख रहा है फिर जब हम उस पर पानी बरसा देते हैं तो लहलहाने और उभरने लगती है और हर तरह की ख़ुशनुमा चीज़ें उगती है तो ये क़ुदरत के तमाशे इसलिए दिखाते हैं ताकि तुम जानो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,6,'Al-Hajj','ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','ان قدرتوں سے ظاہر ہے کہ خدا ہی (قادر مطلق ہے جو) برحق ہے اور یہ کہ وہ مردوں کو زندہ کردیتا ہے۔ اور یہ کہ وہ ہر چیز پر قدرت رکھتا ہے','That is because Allah ˹alone˺ is the Truth, He ˹alone˺ gives life to the dead, and He ˹alone˺ is Most Capable of everything','कि बेशक खुदा बरहक़ है और (ये भी कि) बेशक वही मुर्दों को जिलाता है और वह यक़ीनन हर चीज़ पर क़ादिर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,7,'Al-Hajj','وَأَنَّ ٱلسَّاعَةَ ءَاتِيَةࣱ لَّا رَيۡبَ فِيهَا وَأَنَّ ٱللَّهَ يَبۡعَثُ مَن فِي ٱلۡقُبُورِ','اور یہ کہ قیامت آنے والی ہے۔ اس میں کچھ شک نہیں۔ اور یہ کہ خدا سب لوگوں کو جو قبروں میں ہیں جلا اٹھائے گا','And certainly the Hour is coming, there is no doubt about it. And Allah will surely resurrect those in the graves','और क़यामत यक़ीनन आने वाली है इसमें कोई शक नहीं और बेशक जो लोग क़ब्रों में हैं उनको खुदा दोबारा ज़िन्दा करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,8,'Al-Hajj','وَمِنَ ٱلنَّاسِ مَن يُجَٰدِلُ فِي ٱللَّهِ بِغَيۡرِ عِلۡمࣲ وَلَا هُدࣰ ى وَلَا كِتَٰبࣲ مُّنِيرࣲ‏','اور لوگوں میں کوئی ایسا بھی ہے جو خدا (کی شان) میں بغیر علم (ودانش) کے اور بغیر ہدایت کے اور بغیر کتاب روشن کے جھگڑتا ہے','˹Still˺ there are some who dispute about Allah without knowledge, guidance, or an enlightening scripture','और लोगों में से कुछ ऐसे भी है जो बेजाने बूझे बे हिदायत पाए बगैर रौशन किताब के (जो उसे राह बताए) खुदा की आयतों से मुँह मोडे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,9,'Al-Hajj','ثَانِيَ عِطۡفِهِۦ لِيُضِلَّ عَن سَبِيلِ ٱللَّهِۖ لَهُۥ فِي ٱلدُّنۡيَا خِزۡيࣱۖ وَنُذِيقُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ عَذَابَ ٱلۡحَرِيقِ','(اور تکبر سے) گردن موڑ لیتا (ہے) تاکہ (لوگوں کو) خدا کے رستے سے گمراہ کردے۔ اس کے لئے دنیا میں ذلت ہے۔ اور قیامت کے دن ہم اسے عذاب (آتش) سوزاں کا مزہ چکھائیں گے','turning away ˹in pride˺ to lead ˹others˺ astray from Allah’s Way. They will suffer disgrace in this world, and on the Day of Judgment We will make them taste the torment of burning','(ख्वाहमख्वाह) खुदा के बारे में लड़ने मरने पर तैयार है ताकि (लोगों को) ख़ुदा की राह बहका दे ऐसे (नाबकार) के लिए दुनिया में (भी) रूसवाई है और क़यामत के दिन (भी) हम उसे जहन्नुम के अज़ाब (का मज़ा) चखाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,10,'Al-Hajj','ذَٰلِكَ بِمَا قَدَّمَتۡ يَدَاكَ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمࣲ لِّلۡعَبِيدِ','(اے سرکش) یہ اس (کفر) کی سزا ہے جو تیرے ہاتھوں نے آگے بھیجا ہے اور خدا اپنے بندوں پر ظلم کرنے والا نہیں','˹They will be told,˺ “This is ˹the reward˺ for what your hands have done. And Allah is never unjust to ˹His˺ creation.”','और उस वक्त उससे कहा जाएगा कि ये उन आमाल की सज़ा है जो तेरे हाथों ने पहले से किए हैं और बेशक खुदा बन्दों पर हरगिज़ जुल्म नहीं करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,11,'Al-Hajj','وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفࣲۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ','اور لوگوں میں بعض ایسا بھی ہے جو کنارے پر (کھڑا ہو کر) خدا کی عبادت کرتا ہے۔ اگر اس کو کوئی (دنیاوی) فائدہ پہنچے تو اس کے سبب مطمئن ہوجائے اور اگر کوئی آفت پڑے تو منہ کے بل لوٹ جائے (یعنی پھر کافر ہوجائے) اس نے دنیا میں بھی نقصان اٹھایا اور آخرت میں بھی۔ یہی تو نقصان صریح ہے','And there are some who worship Allah on the verge ˹of faith˺: if they are blessed with something good, they are content with it; but if they are afflicted with a trial, they relapse ˹into disbelief˺, losing this world and the Hereafter. That is ˹truly˺ the clearest loss','और लोगों में से कुछ ऐसे भी हैं जो एक किनारे पर (खड़े होकर) खुदा की इबादत करता है तो अगर उसको कोई फायदा पहुँच गया तो उसकी वजह से मुतमईन हो गया और अगर कहीं उस कोई मुसीबत छू भी गयी तो (फौरन) मुँह फेर के (कुफ़्र की तरफ़) पलट पड़ा उसने दुनिया और आखेरत (दोनों) का घाटा उठाया यही तो सरीही घाटा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,12,'Al-Hajj','يَدۡعُواْ مِن دُونِ ٱللَّهِ مَا لَا يَضُرُّهُۥ وَمَا لَا يَنفَعُهُۥۚ ذَٰلِكَ هُوَ ٱلضَّلَٰلُ ٱلۡبَعِيدُ','یہ خدا کے سوا ایسی چیز کو پکارتا ہے جو نہ اسے نقصان پہنچائے اور نہ فائدہ دے سکے۔ یہی تو پرلے درجے کی گمراہی ہے','They call besides Allah what can neither harm nor benefit them. That is ˹truly˺ the farthest one can stray','खुदा को छोड़कर उन चीज़ों को (हाजत के वक्त) बुलाता है जो न उसको नुक़सान ही पहुँचा सकते हैं और न कुछ नफा ही पहुँचा सकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,13,'Al-Hajj','يَدۡعُواْ لَمَن ضَرُّهُۥٓ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِيرُ','ایسے شخص کو پکارتا ہے جس کا نقصان فائدہ سے زیادہ قریب ہے۔ ایسا دوست برا بھی اور ایسا ہم صحبت بھی برا','They invoke those whose worship leads to harm, not benefit. What an evil patron and what an evil associate','यही तो पल्ले दरने की गुमराही है और उसको अपनी हाजत रवाई के लिए पुकारता है जिस का नुक़सान उसके नफे से ज्यादा क़रीब है बेशक ऐसा मालिक भी बुरा और ऐसा रफीक़ भी बुरा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,14,'Al-Hajj','إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يُرِيدُ','جو لوگ ایمان لائے اور عمل نیک کرتے رہے خدا ان کو بہشتوں میں داخل کرے گا جن کے نیچے نہریں چل رہیں ہیں۔ کچھ شک نہیں کہ خدا جو چاہتا ہے کرتا ہے','Indeed, Allah will admit those who believe and do good into Gardens, under which rivers flow. Surely Allah does what He wills','बेशक जिन लोगों ने ईमान कुबूल किया और अच्छे अच्छे काम किए उनको (खुदा बेहश्त के) उन (हरे-भरे) बाग़ात में ले जाकर दाख़िल करेगा जिनके नीचे नहरें जारी होगीं बेशक खुदा जो चाहता है करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,15,'Al-Hajj','مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ ٱللَّهُ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ فَلۡيَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَآءِ ثُمَّ لۡيَقۡطَعۡ فَلۡيَنظُرۡ هَلۡ يُذۡهِبَنَّ كَيۡدُهُۥ مَا يَغِيظُ','جو شخص یہ گمان کرتا ہے کہ خدا اس کو دنیا اور آخرت میں مدد نہیں دے گا تو اس کو چاہیئے کہ اوپر کی طرف (یعنی اپنے گھر کی چھت میں) ایک رسی باندھے پھر (اس سے اپنا) گلا گھونٹ لے۔ پھر دیکھے کہ آیا یہ تدبیر اس کے غصے کو دور کردیتی ہے','Whoever thinks that Allah will not help His Prophet in this world and the Hereafter, let them stretch out a rope to the ceiling and strangle themselves, then let them see if this plan will do away with ˹the cause of˺ their rage','जो शख्स (गुस्से में) ये बदगुमानी करता है कि दुनिया और आख़ेरत में खुदा उसकी हरग़िज मदद न करेगा तो उसे चाहिए कि आसमान तक रस्सी ताने (और अपने गले में फाँसी डाल दे) फिर उसे काट दे (ताकि घुट कर मर जाए) फिर देखिए कि जो चीज़ उसे गुस्से में ला रही थी उसे उसकी तद्बीर दूर दफ़ा कर देती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,16,'Al-Hajj','وَكَذَٰلِكَ أَنزَلۡنَٰهُ ءَايَٰتِۭ بَيِّنَٰتࣲ وَأَنَّ ٱللَّهَ يَهۡدِي مَن يُرِيدُ','اور اسی طرح ہم نے اس قرآن کو اُتارا ہے (جس کی تمام) باتیں کھلی ہوئی (ہیں) اور یہ (یاد رکھو) کہ خدا جس کو چاہتا ہے ہدایات دیتا ہے','And so We revealed this ˹Quran˺ as clear verses. And Allah certainly guides whoever He wills','(या नहीं) और हमने इस कुरान को यूँ ही वाजेए व रौशन निशानियाँ (बनाकर) नाज़िल किया और बेशक खुदा जिसकी चाहता है हिदायत करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,17,'Al-Hajj','إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ','جو لوگ مومن (یعنی مسلمان) ہیں اور جو یہودی ہیں اور ستارہ پرست اور عیسائی اور مجوسی اور مشرک۔ خدا ان (سب) میں قیامت کے دن فیصلہ کردے گا۔ بےشک خدا ہر چیز سے باخبر ہے','Indeed, the believers, Jews, Sabians, Christians, Magi, and the polytheists—Allah will judge between them ˹all˺ on Judgment Day. Surely Allah is a Witness over all things','इसमें शक नहीं कि जिन लोगों ने ईमान कुबूल किया (मुसलमान) और यहूदी और लामज़हब लोग और ईसाई और मजूसी (आतिशपरस्त) और मुशरेकीन (कुफ्फ़ार) यक़ीनन खुदा उन लोगों के दरमियान क़यामत के दिन (ठीक ठीक) फ़ैसला कर देगा इसमें शक नहीं कि खुदा हर चीज़ को देख रहा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,18,'Al-Hajj','أَلَمۡ تَرَ أَنَّ ٱللَّهَ يَسۡجُدُۤ لَهُۥۤ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَآبُّ وَكَثِيرࣱ مِّنَ ٱلنَّاسِۖ وَكَثِيرٌ حَقَّ عَلَيۡهِ ٱلۡعَذَابُۗ وَمَن يُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ يَفۡعَلُ مَا يَشَآءُ۩','کیا تم نے نہیں دیکھا کہ جو (مخلوق) آسمانوں میں ہے اور جو زمین میں ہے اور سورج اور چاند ستارے اور پہاڑ اور درخت اور چار پائے اور بہت سے انسان خدا کو سجدہ کرتے ہیں۔ اور بہت سے ایسے ہیں جن پر عذاب ثابت ہوچکا ہے۔ اور جس شخص کو خدا ذلیل کرے اس کو عزت دینے والا نہیں۔ بےشک خدا جو چاہتا ہے کرتا ہے','Do you not see that to Allah bow down ˹in submission˺ all those in the heavens and all those on the earth, as well as the sun, the moon, the stars, the mountains, the trees, and ˹all˺ living beings, as well as many humans, while many are deserving of punishment. And whoever Allah disgraces, none can honour. Surely Allah does what He wills','क्या तुमने इसको भी नहीं देखा कि जो लोग आसमानों में हैं और जो लोग ज़मीन में हैं और आफताब और माहताब और सितारे और पहाड़ और दरख्त और चारपाए (ग़रज़ कुल मख़लूक़ात) और आदमियों में से बहुत से लोग सब खुदा ही को सजदा करते हैं और बहुतेरे ऐसे भी हैं जिन पर नाफ़रमानी की वजह से अज़ाब का (का आना) लाज़िम हो चुका है और जिसको खुदा ज़लील करे फिर उसका कोई इज्ज़त देने वाला नहीं कुछ शक नहीं कि खुदा जो चाहता है करता है (18) सजदा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,19,'Al-Hajj','۞هَٰذَانِ خَصۡمَانِ ٱخۡتَصَمُواْ فِي رَبِّهِمۡۖ فَٱلَّذِينَ كَفَرُواْ قُطِّعَتۡ لَهُمۡ ثِيَابࣱ مِّن نَّارࣲ يُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِيمُ','یہ دو (فریق) ایک دوسرے کے دشمن اپنے پروردگار (کے بارے) میں جھگڑتے ہیں۔ تو کافر ہیں ان کے لئے آگ کے کپڑے قطع کئے جائیں گے (اور) ان کے سروں پر جلتا ہوا پانی ڈالا جائے گا','These are two opposing groups that disagree about their Lord: as for the disbelievers, garments of Fire will be cut out for them and boiling water will be poured over their heads','ये दोनों (मोमिन व काफिर) दो फरीक़ हैं आपस में अपने परवरदिगार के बारे में लड़ते हैं ग़रज़ जो लोग काफ़िर हो बैठे उनके लिए तो आग के कपड़े केता किए गए हैं (वह उन्हें पहनाए जाएँगें और) उनके सरों पर खौलता हुआ पानी उँडेला जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,20,'Al-Hajj','يُصۡهَرُ بِهِۦ مَا فِي بُطُونِهِمۡ وَٱلۡجُلُودُ','اس سے ان کے پیٹ کے اندر کی چیزیں اور کھالیں گل جائیں گی','melting whatever is in their bellies, along with their skin','जिस (की गर्मी) से जो कुछ उनके पेट में है (ऑंतें वग़ैरह) और खालें सब गल जाएँगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,21,'Al-Hajj','وَلَهُم مَّقَٰمِعُ مِنۡ حَدِيدࣲ‏','اور ان (کے مارنے ٹھوکنے) کے لئے لوہے کے ہتھوڑے ہوں گے','And awaiting them are maces of iron','और उनके (मारने के) लिए लोहे के गुर्ज़ होंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,22,'Al-Hajj','كُلَّمَآ أَرَادُوٓاْ أَن يَخۡرُجُواْ مِنۡهَا مِنۡ غَمٍّ أُعِيدُواْ فِيهَا وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ','جب وہ چاہیں گے کہ اس رنج (وتکلیف) کی وجہ سے دوزخ سے نکل جائیں تو پھر اسی میں لوٹا دیئے جائیں گے۔ اور (کہا جائے گا کہ) جلنے کے عذاب کا مزہ چکھتے رہو','Whenever they try to escape from Hell—out of anguish—they will be forced back into it, ˹and will be told,˺ “Taste the torment of burning!”','कि जब सदमें के मारे चाहेंगे कि दोज़ख़ से निकल भागें तो (ग़ुर्ज मार के) फिर उसके अन्दर ढकेल दिए जाएँगे और (उनसे कहा जाएगा कि) जलाने वाले अज़ाब के मज़े चखो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,23,'Al-Hajj','إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰ اۖ وَلِبَاسُهُمۡ فِيهَا حَرِيرࣱ‏','جو لوگ ایمان لائے اور عمل نیک کرتے رہے خدا ان کو بہشتوں میں داخل کرے گا جن کے تلے نہریں بہہ رہیں ہیں۔ وہاں ان کو سونے کے کنگن پہنائے جائیں گے اور موتی۔ اور وہاں ان کا لباس ریشمی ہوگا','˹But˺ Allah will surely admit those who believe and do good into Gardens, under which rivers flow, where they will be adorned with bracelets of gold and pearls, and their clothing will be silk','जो लोग ईमान लाए और उन्होंने अच्छे अच्छे काम भी किए उनको खुदा बेहश्त के ऐसे हरे-भरे बाग़ों में दाख़िल फरमाएगा जिनके नीचे नहरे जारी होगी उन्हें वहाँ सोने के कंगन और मोती (के हार) से सँवारा जाएगा और उनका लिबास वहाँ रेशमी होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,24,'Al-Hajj','وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ','اور ان کو پاکیزہ کلام کی ہدایت کی گئی اور (خدائے) حمید کی راہ بتائی گئی','for they have been guided to the best of speech, and they have been guided to the Commendable Path','और (ये इस वजह से कि दुनिया में) उन्हें अच्छी बात (कलमाए तौहीद) की हिदायत की गई और उन्हें सज़ावारे हम्द (खुदा) का रास्ता दिखाया गया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,25,'Al-Hajj','إِنَّ ٱلَّذِينَ كَفَرُواْ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِي جَعَلۡنَٰهُ لِلنَّاسِ سَوَآءً ٱلۡعَٰكِفُ فِيهِ وَٱلۡبَادِۚ وَمَن يُرِدۡ فِيهِ بِإِلۡحَادِۭ بِظُلۡمࣲ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِيمࣲ‏','جو لوگ کافر ہیں اور (لوگوں کو) خدا کے رستے سے اور مسجد محترم سے جسے ہم نے لوگوں کے لئے یکساں (عبادت گاہ) بنایا ہے روکتے ہیں۔ خواہ وہاں کے رہنے والے ہوں یا باہر سے آنے والے۔ اور جو اس میں شرارت سے کج روی (وکفر) کرنا چاہے اس کو ہم درد دینے والے عذاب کا مزہ چکھائیں گے۔','Indeed, those who persist in disbelief and hinder ˹others˺ from the Way of Allah and from the Sacred Mosque—which We have appointed for all people, residents and visitors alike—along with whoever intends to deviate by doing wrong in it, We will cause them to taste a painful punishment','बेशक जो लोग काफिर हो बैठे और खुदा की राह से और मस्जिदें मोहतरम (ख़ानए काबा) से जिसे हमने सब लोगों के लिए (माबद) बनाया है (और) इसमें शहरी और बेरूनी सबका हक़ बराबर है (लोगों को) रोकते हैं (उनको) और जो शख्स इसमें शरारत से गुमराही करे उसको हम दर्दनाक अज़ाब का मज़ा चखा देंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,26,'Al-Hajj','وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـࣰٔ ا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ','(اور ایک وقت تھا) جب ہم نے ابراہیم کے لئے خانہ کعبہ کو مقرر کیا (اور ارشاد فرمایا) کہ میرے ساتھ کسی چیز کو شریک نہ کیجیو اور طواف کرنے والوں اور قیام کرنے والوں اور رکوع کرنے والوں (اور) سجدہ کرنے والوں کے لئے میرے گھر کو صاف رکھا کرو','And ˹remember˺ when We assigned to Abraham the site of the House, ˹saying,˺ “Do not associate anything with Me ˹in worship˺ and purify My House for those who circle ˹the Ka’bah˺, stand ˹in prayer˺, and bow and prostrate themselves','और (ऐ रसूल वह वक्त याद करो) जब हमने इबराहीम के ज़रिये से इबरहीम के वास्ते ख़ानए काबा की जगह ज़ाहिर कर दी (और उनसे कहा कि) मेरा किसी चीज़ को शरीक न बनाना और मेरे घर को तवाफ और क़याम और रूकू सुजूद करने वालों के वास्ते साफ सुथरा रखना');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,27,'Al-Hajj','وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ يَأۡتُوكَ رِجَالࣰ ا وَعَلَىٰ كُلِّ ضَامِرࣲ يَأۡتِينَ مِن كُلِّ فَجٍّ عَمِيقࣲ‏','اور لوگوں میں حج کے لئے ندا کر دو کہ تمہاری پیدل اور دبلے دبلے اونٹوں پر جو دور دراز رستوں سے چلے آتے ہو (سوار ہو کر) چلے آئیں','Call ˹all˺ people to the pilgrimage. They will come to you on foot and on every lean camel from every distant path','और लोगों को हज की ख़बर कर दो कि लोग तुम्हारे पास (ज़ूक दर ज़ूक) ज्यादा और हर तरह की दुबली (सवारियों पर जो राह दूर दराज़ तय करके आयी होगी चढ़-चढ़ के) आ पहुँचेगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,28,'Al-Hajj','لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ وَيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ فِيٓ أَيَّامࣲ مَّعۡلُومَٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۖ فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡبَآئِسَ ٱلۡفَقِيرَ','تاکہ اپنے فائدے کے کاموں کے لئے حاضر ہوں۔ اور (قربانی کے) ایام معلوم میں چہار پایاں مویشی (کے ذبح کے وقت) جو خدا نے ان کو دیئے ہیں ان پر خدا کا نام لیں۔ اس میں سے تم خود بھی کھاؤ اور فقیر درماندہ کو بھی کھلاؤ','so they may obtain the benefits ˹in store˺ for them, and pronounce the Name of Allah on appointed days over the sacrificial animals He has provided for them. So eat from their meat and feed the desperately poor','ताकि अपने (दुनिया व आखेरत के) फायदो पर फायज़ हों और खुदा ने जो जानवर चारपाए उन्हें अता फ़रमाए उनपर (ज़िबाह के वक्त) चन्द मुअय्युन दिनों में खुदा का नाम लें तो तुम लोग कुरबानी के गोश्त खुद भी खाओ और भूखे मोहताज को भी खिलाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,29,'Al-Hajj','ثُمَّ لۡيَقۡضُواْ تَفَثَهُمۡ وَلۡيُوفُواْ نُذُورَهُمۡ وَلۡيَطَّوَّفُواْ بِٱلۡبَيۡتِ ٱلۡعَتِيقِ','پھر چاہیئے کہ لوگ اپنا میل کچیل دور کریں اور نذریں پوری کریں اور خانہٴ قدیم (یعنی بیت الله) کا طواف کریں','Then let them groom themselves, fulfil their vows, and circle the Ancient House.”','फिर लोगों को चाहिए कि अपनी-अपनी (बदन की) कसाफ़त दूर करें और अपनी नज़रें पूरी करें और क़दीम (इबादत) ख़ानए काबा का तवाफ करें यही हुक्म है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,30,'Al-Hajj','ذَٰلِكَۖ وَمَن يُعَظِّمۡ حُرُمَٰتِ ٱللَّهِ فَهُوَ خَيۡرࣱ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَٰمُ إِلَّا مَا يُتۡلَىٰ عَلَيۡكُمۡۖ فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ وَٱجۡتَنِبُواْ قَوۡلَ ٱلزُّورِ','یہ (ہمارا حکم ہے) جو شخص ادب کی چیزوں کی جو خدا نے مقرر کی ہیں عظمت رکھے تو یہ پروردگار کے نزدیک اس کے حق میں بہتر ہے۔ اور تمہارے لئے مویشی حلال کردیئے گئے ہیں۔ سوا ان کے جو تمہیں پڑھ کر سنائے جاتے ہیں تو بتوں کی پلیدی سے بچو اور جھوٹی بات سے اجتناب کرو','That is so. And whoever honours the rituals of Allah, it is best for them in the sight of their Lord. The ˹meat of˺ cattle has been made lawful for you, except what has ˹already˺ been recited to you. So shun the impurity of idolatry, and shun words of falsehood','और इसके अलावा जो शख्स खुदा की हुरमत वाली चीज़ों की ताज़ीम करेगा तो ये उसके पवरदिगार के यहाँ उसके हक़ में बेहतर है और उन जानवरों के अलावा जो तुमसे बयान किए जाँएगे कुल चारपाए तुम्हारे वास्ते हलाल किए गए तो तुम नापाक बुतों से बचे रहो और लग़ो बातें गाने वग़ैरह से बचे रहो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,31,'Al-Hajj','حُنَفَآءَ لِلَّهِ غَيۡرَ مُشۡرِكِينَ بِهِۦۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَآءِ فَتَخۡطَفُهُ ٱلطَّيۡرُ أَوۡ تَهۡوِي بِهِ ٱلرِّيحُ فِي مَكَانࣲ سَحِيقࣲ‏','صرف ایک خدا کے ہو کر اس کے ساتھ شریک نہ ٹھیرا کر۔ اور جو شخص (کسی کو) خدا کے ساتھ شریک مقرر کرے تو وہ گویا ایسا ہے جیسے آسمان سے گر پڑے پھر اس کو پرندے اُچک لے جائیں یا ہوا کسی دور جگہ اُڑا کر پھینک دے','Be upright ˹in devotion˺ to Allah, associating none with Him ˹in worship˺. For whoever associates ˹others˺ with Allah is like someone who has fallen from the sky and is either snatched away by birds or swept by the wind to a remote place','निरे खरे अल्लाह के होकर (रहो) उसका किसी को शरीक न बनाओ और जिस शख्स ने (किसी को) खुदा का शरीक बनाया तो गोया कि वह आसमान से गिर पड़ा फिर उसको (या तो दरमियान ही से) कोई (मुरदा ख्ववार) चिड़िया उचक ले गई या उसे हवा के झोंके ने बहुत दूर जा फेंका');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,32,'Al-Hajj','ذَٰلِكَۖ وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ','(یہ ہمارا حکم ہے) اور جو شخص ادب کی چیزوں کی جو خدا نے مقرر کی ہیں عظمت رکھے تو یہ (فعل) دلوں کی پرہیزگاری میں سے ہے','That is so. And whoever honours the symbols of Allah, it is certainly out of the piety of the heart','ये (याद रखो) और जिस शख्स ने खुदा की निशानियों की ताज़ीम की तो कुछ शक नहीं कि ये भी दिलों की परहेज़गारी से हासिल होती है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,33,'Al-Hajj','لَكُمۡ فِيهَا مَنَٰفِعُ إِلَىٰٓ أَجَلࣲ مُّسَمࣰّ ى ثُمَّ مَحِلُّهَآ إِلَى ٱلۡبَيۡتِ ٱلۡعَتِيقِ','ان میں ایک وقت مقرر تک تمہارے لئے فائدے ہیں پھر ان کو خانہٴ قدیم (یعنی بیت الله) تک پہنچانا (اور ذبح ہونا) ہے','You may benefit from sacrificial animals for an appointed term, then their place of sacrifice is at the Ancient House','और इन चार पायों में एक मुअय्युन मुद्दत तक तुम्हार लिये बहुत से फायदें हैं फिर उनके ज़िबाह होने की जगह क़दीम (इबादत) ख़ानए काबा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,34,'Al-Hajj','وَلِكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكࣰ ا لِّيَذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِيمَةِ ٱلۡأَنۡعَٰمِۗ فَإِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱ فَلَهُۥٓ أَسۡلِمُواْۗ وَبَشِّرِ ٱلۡمُخۡبِتِينَ','اور ہم نے ہر اُمت کے لئے قربانی کا طریق مقرر کردیا ہے تاکہ جو مویشی چارپائے خدا نے ان کو دیئے ہیں (ان کے ذبح کرنے کے وقت) ان پر خدا کا نام لیں۔ سو تمہارا معبود ایک ہی ہے تو اسی کے فرمانبردار ہوجاؤ۔ اور عاجزی کرنے والوں کو خوشخبری سنادو','For every community We appointed a rite of sacrifice so that they may pronounce the Name of Allah over the sacrificial animals He has provided for them. For your God is only One God, so submit yourselves to Him ˹alone˺. And give good news ˹O Prophet˺ to the humble','और हमने तो हर उम्मत के वास्ते क़ुरबानी का तरीक़ा मुक़र्रर कर दिया है ताकि जो मवेशी चारपाए खुदा ने उन्हें अता किए हैं उन पर (ज़िबाह के वक्त) ख़ुदा का नाम ले ग़रज़ तुम लोगों का माबूद (वही) यकता खुदा है तो उसी के फरमाबरदार बन जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,35,'Al-Hajj','ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّٰبِرِينَ عَلَىٰ مَآ أَصَابَهُمۡ وَٱلۡمُقِيمِي ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ','یہ وہ لوگ ہیں کہ جب خدا کا نام لیا جاتا ہے تو ان کے دل ڈر جاتے ہیں اور جب ان پر مصیبت پڑتی ہے تو صبر کرتے ہیں اور نماز آداب سے پڑھتے ہیں اور جو (مال) ہم نے ان کو عطا فرمایا ہے (اس میں سے) (نیک کاموں میں) خرچ کرتے ہیں','those whose hearts tremble at the remembrance of Allah, who patiently endure whatever may befall them, and who establish prayer and donate from what We have provided for them','और (ऐ रसूल हमारे) गिड़गिड़ाने वाले बन्दों को (बेहश्त की) खुशख़बरी दे दो ये वह हैं कि जब (उनके सामने) खुदा का नाम लिया जाता है तो उनके दिल सहम जाते हैं और जब उनपर कोई मुसीबत आ पड़े तो सब्र करते हैं और नमाज़ पाबन्दी से अदा करते हैं और जो कुछ हमने उन्हें दे रखा है उसमें से (राहे खुदा में) ख़र्च करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,36,'Al-Hajj','وَٱلۡبُدۡنَ جَعَلۡنَٰهَا لَكُم مِّن شَعَٰٓئِرِ ٱللَّهِ لَكُمۡ فِيهَا خَيۡرࣱۖ فَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهَا صَوَآفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُواْ مِنۡهَا وَأَطۡعِمُواْ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَٰلِكَ سَخَّرۡنَٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ','اور قربانی کے اونٹوں کو بھی ہم نے تمہارے لئے شعائر خدا مقرر کیا ہے۔ ان میں تمہارے لئے فائدے ہیں۔ تو (قربانی کرنے کے وقت) قطار باندھ کر ان پر خدا کا نام لو۔ جب پہلو کے بل گر پڑیں تو ان میں سے کھاؤ اور قناعت سے بیٹھ رہنے والوں اور سوال کرنے والوں کو بھی کھلاؤ۔ اس طرح ہم نے ان کو تمہارے زیرفرمان کردیا ہے تاکہ تم شکر کرو','We have made sacrificial camels ˹and cattle˺ among the symbols of Allah, in which there is ˹much˺ good for you. So pronounce the Name of Allah over them when they are lined up ˹for sacrifice˺. Once they have fallen ˹lifeless˺ on their sides, you may eat from their meat, and feed the needy—those who do not beg, and those who do. In this way We have subjected these ˹animals˺ to you so that you may be grateful','और कुरबानी (मोटे गदबदे) ऊँट भी हमने तुम्हारे वास्ते खुदा की निशानियों में से क़रार दिया है इसमें तुम्हारी बहुत सी भलाईयाँ हैं फिर उनका तांते का तांता बाँध कर ज़िबाह करो और उस वक्त उन पर खुदा का नाम लो फिर जब उनके दस्त व बाजू काटकर गिर पड़े तो उन्हीं से तुम खुद भी खाओ और केनाअत पेशा फक़ीरों और माँगने वाले मोहताजों (दोनों) को भी खिलाओ हमने यूँ इन जानवरों को तुम्हारा ताबेए कर दिया ताकि तुम शुक्रगुज़ार बनो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,37,'Al-Hajj','لَن يَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَآؤُهَا وَلَٰكِن يَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِينَ','خدا تک نہ اُن کا گوشت پہنچتا ہے اور نہ خون۔ بلکہ اس تک تمہاری پرہیزگاری پہنچتی ہے۔ اسی طرح خدا نے ان کو تمہارا مسخر کر دیا ہے تاکہ اس بات کے بدلے کہ اس نے تم کو ہدایت بخشی ہے اسے بزرگی سے یاد کرو۔ اور (اے پیغمبر) نیکوکاروں کو خوشخبری سنا دو','Neither their meat nor blood reaches Allah. Rather, it is your piety that reaches Him. This is how He has subjected them to you so that you may proclaim the greatness of Allah for what He has guided you to, and give good news to the good-doers','खुदा तक न तो हरगिज़ उनके गोश्त ही पहुँचेगे और न खून मगर (हाँ) उस तक तुम्हारी परहेज़गारी अलबत्ता पहुँचेगी ख़ुदा ने जानवरों को (इसलिए) यूँ तुम्हारे क़ाबू में कर दिया है ताकि जिस तरह खुदा ने तुम्हें बनाया है उसी तरह उसकी बड़ाई करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,38,'Al-Hajj','۞إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْۗ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ','خدا تو مومنوں سے ان کے دشمنوں کو ہٹاتا رہتا ہے۔ بےشک خدا کسی خیانت کرنے والے اور کفران نعمت کرنے والے کو دوست نہیں رکھتا۔','Indeed, Allah defends those who believe. Surely Allah does not like whoever is deceitful, ungrateful','और (ऐ रसूल) नेकी करने वालों को (हमेशा की) ख़ुशख़बरी दे दो इसमें शक नहीं कि खुदा ईमानवालों से कुफ्फ़ार को दूर दफा करता रहता है खुदा किसी बददयानत नाशुक्रे को हरगिज़ दोस्त नहीं रखता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,39,'Al-Hajj','أُذِنَ لِلَّذِينَ يُقَٰتَلُونَ بِأَنَّهُمۡ ظُلِمُواْۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِيرٌ','جن مسلمانوں سے (خواہ مخواہ) لڑائی کی جاتی ہے ان کو اجازت ہے (کہ وہ بھی لڑیں) کیونکہ ان پر ظلم ہو رہا ہے۔ اور خدا (ان کی مدد کرے گا وہ) یقیناً ان کی مدد پر قادر ہے','Permission ˹to fight back˺ is ˹hereby˺ granted to those being fought, for they have been wronged. And Allah is truly Most Capable of helping them ˹prevail˺','जिन (मुसलमानों) से (कुफ्फ़ार) लड़ते थे चूँकि वह (बहुत) सताए गए उस वजह से उन्हें भी (जिहाद) की इजाज़त दे दी गई और खुदा तो उन लोगों की मदद पर यक़ीनन क़ादिर (वत वाना) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,40,'Al-Hajj','ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرࣰ اۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ','یہ وہ لوگ ہیں کہ اپنے گھروں سے ناحق نکال دیئے گئے (انہوں نے کچھ قصور نہیں کیا) ہاں یہ کہتے ہیں کہ ہمارا پروردگار خدا ہے۔ اور اگر خدا لوگوں کو ایک دوسرے سے نہ ہٹاتا رہتا تو (راہبوں کے) صومعے اور (عیسائیوں کے) گرجے اور (یہودیوں کے) عبادت خانے اور (مسلمانوں کی) مسجدیں جن میں خدا کا بہت سا ذکر کیا جاتا ہے ویران ہوچکی ہوتیں۔ اور جو شخص خدا کی مدد کرتا ہے خدا اس کی ضرور مدد کرتا ہے۔ بےشک خدا توانا اور غالب ہے','˹They are˺ those who have been expelled from their homes for no reason other than proclaiming: “Our Lord is Allah.” Had Allah not repelled ˹the aggression of˺ some people by means of others, destruction would have surely claimed monasteries, churches, synagogues, and mosques in which Allah’s Name is often mentioned. Allah will certainly help those who stand up for Him. Allah is truly All-Powerful, Almighty','ये वह (मज़लूम हैं जो बेचारे) सिर्फ इतनी बात कहने पर कि हमारा परवरदिगार खुदा है (नाहक़) अपने-अपने घरों से निकाल दिए गये और अगर खुदा लोगों को एक दूसरे से दूर दफा न करता रहता तो गिरजे और यहूदियों के इबादत ख़ाने और मजूस के इबादतख़ाने और मस्जिद जिनमें कसरत से खुदा का नाम लिया जाता है कब के कब ढहा दिए गए होते और जो शख्स खुदा की मदद करेगा खुदा भी अलबत्ता उसकी मदद ज़रूर करेगा बेशक खुदा ज़रूर ज़बरदस्त ग़ालिब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,41,'Al-Hajj','ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ','یہ وہ لوگ ہیں کہ اگر ہم ان کو ملک میں دسترس دیں تو نماز پڑھیں اور زکوٰة ادا کریں اور نیک کام کرنے کا حکم دیں اور برے کاموں سے منع کریں اور سب کاموں کا انجام خدا ہی کے اختیار میں ہے','˹They are˺ those who, if established in the land by Us, would perform prayer, pay alms-tax, encourage what is good, and forbid what is evil. And with Allah rests the outcome of all affairs','ये वह लोग हैं कि अगर हम इन्हें रूए ज़मीन पर क़ाबू दे दे तो भी यह लोग पाबन्दी से नमाजे अदा करेंगे और ज़कात देंगे और अच्छे-अच्छे काम का हुक्म करेंगे और बुरी बातों से (लोगों को) रोकेंगे और (यूँ तो) सब कामों का अन्जाम खुदा ही के एख्तेयार में है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,42,'Al-Hajj','وَإِن يُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَثَمُودُ','اور اگر یہ لوگ تم کو جھٹلاتے ہیں ان سے پہلے نوح کی قوم اور عاد وثمود بھی (اپنے پیغمبروں کو) جھٹلا چکے ہیں','If they deny you ˹O Prophet˺, so did the people of Noah before them, as well as ˹the tribes of˺ ’Ȃd and Thamûd','और (ऐ रसूल) अगर ये (कुफ्फ़ार) तुमको झुठलाते हैं तो कोइ ताज्जुब की बात नहीं उनसे पहले नूह की क़ौम और (क़ौमे आद और समूद)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,43,'Al-Hajj','وَقَوۡمُ إِبۡرَٰهِيمَ وَقَوۡمُ لُوطࣲ‏','اور قوم ابراہیم اور قوم لوط بھی','the people of Abraham, the people of Lot','और इबराहीम की क़ौम और लूत की क़ौम');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,44,'Al-Hajj','وَأَصۡحَٰبُ مَدۡيَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَيۡتُ لِلۡكَٰفِرِينَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ نَكِيرِ','اور مدین کے رہنے والے بھی۔ اور موسیٰ بھی تو جھٹلائے جاچکے ہیں لیکن میں کافروں کو مہلت دیتا رہا پھر ان کو پکڑ لیا۔ تو (دیکھ لو) کہ میرا عذاب کیسا (سخت) تھا','and the residents of Midian. And Moses was denied ˹too˺. But I delayed ˹the fate of˺ the disbelievers ˹until their appointed time˺ then seized them. And how severe was My response','और मदियन के रहने वाले (अपने-अपने पैग़म्बरों को) झुठला चुके हैं और मूसा (भी) झुठलाए जा चुके हैं तो मैंने काफिरों को चन्द ढील दे दी फिर (आख़िर) उन्हें ले डाला तो तुमने देखा मेरा अज़ाब कैसा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,45,'Al-Hajj','فَكَأَيِّن مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا وَهِيَ ظَالِمَةࣱ فَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرࣲ مُّعَطَّلَةࣲ وَقَصۡرࣲ مَّشِيدٍ','اور بہت سی بستیاں ہیں کہ ہم نے ان کو تباہ کر ڈالا کہ وہ نافرمان تھیں۔ سو وہ اپنی چھتوں پر گری پڑی ہیں۔ اور (بہت سے) کنوئیں بےکار اور (بہت سے) محل ویران پڑے ہیں','Many are the societies We have destroyed for persisting in wrongdoing, leaving them in total ruin. ˹Many are˺ also the abandoned wells and lofty palaces','ग़रज़ कितनी बस्तियाँ हैं कि हम ने उन्हें बरबाद कर दिया और वह सरकश थीं पस वह अपनी छतों पर ढही पड़ी हैं और कितने बेकार (उजडे क़ुएँ और कितने) मज़बूत बड़े-बड़े ऊँचे महल (वीरान हो गए)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,46,'Al-Hajj','أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبࣱ يَعۡقِلُونَ بِهَآ أَوۡ ءَاذَانࣱ يَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَٰرُ وَلَٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِي فِي ٱلصُّدُورِ','کیا ان لوگوں نے ملک میں سیر نہیں کی تاکہ ان کے دل (ایسے) ہوتے کہ ان سے سمجھ سکتے۔ اور کان (ایسے) ہوتے کہ ان سے سن سکتے۔ بات یہ ہے کہ آنکھیں اندھی نہیں ہوتیں بلکہ دل جو سینوں میں ہیں (وہ) اندھے ہوتے ہیں','Have they not travelled throughout the land so their hearts may reason, and their ears may listen? Indeed, it is not the eyes that are blind, but it is the hearts in the chests that grow blind','क्या ये लोग रूए ज़मीन पर चले फिरे नहीं ताकि उनके लिए ऐसे दिल होते हैं जैसे हक़ बातों को समझते या उनके ऐसे कान होते जिनके ज़रिए से (सच्ची बातों को) सुनते क्योंकि ऑंखें अंधी नहीं हुआ करती बल्कि दिल जो सीने में है वही अन्धे हो जाया करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,47,'Al-Hajj','وَيَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن يُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ يَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةࣲ مِّمَّا تَعُدُّونَ','اور (یہ لوگ) تم سے عذاب کے لئے جلدی کر رہے ہیں اور خدا اپنا وعدہ ہرگز خلاف نہیں کرے گا۔ اور بےشک تمہارے پروردگار کے نزدیک ایک روز تمہارے حساب کے رو سے ہزار برس کے برابر ہے','They challenge you ˹O Prophet˺ to hasten the torment. And Allah will never fail in His promise. But a day with your Lord is indeed like a thousand years by your counting','और (ऐ रसूल) तुम से ये लोग अज़ाब के जल्द आने की तमन्ना रखते हैं और खुदा तो हरगिज़ अपने वायदे के ख़िलाफ नहीं करेगा और बेशक (क़यामत का) एक दिन तुम्हारे परवरदिगार के नज़दीक तुम्हारी गिनती के हिसाब से एक हज़ार बरस के बराबर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,48,'Al-Hajj','وَكَأَيِّن مِّن قَرۡيَةٍ أَمۡلَيۡتُ لَهَا وَهِيَ ظَالِمَةࣱ ثُمَّ أَخَذۡتُهَا وَإِلَيَّ ٱلۡمَصِيرُ','اور بہت سی بستیاں ہیں کہ میں ان کو مہلت دیتا رہا اور وہ نافرمان تھیں۔ پھر میں نے ان کو پکڑ لیا۔ اور میری طرف ہی لوٹ کر آنا ہے','Many are the societies whose end We delayed while they did wrong, then seized them. And to Me is the final return','और कितनी बस्तियाँ हैं कि मैंने उन्हें (चन्द) मोहलत दी हालाँकि वह सरकश थी फिर (आख़िर) मैंने उन्हें ले डाला और (सबको) मेरी तरफ लौटना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,49,'Al-Hajj','قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّمَآ أَنَا۠ لَكُمۡ نَذِيرࣱ مُّبِينࣱ‏','(اے پیغمبر) کہہ دو کہ لوگو! میں تم کو کھلم کھلا نصیحت کرنے والا ہوں','Say, ˹O Prophet,˺ “O humanity! I am only sent to you with a clear warning','(ऐ रसूल) तुम कह दो कि लोगों में तो सिर्फ तुमको खुल्लम-खुल्ला (अज़ाब से) डराने वाला हूँ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,50,'Al-Hajj','فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِيمࣱ‏','تو جو لوگ ایمان لائے اور نیک کام کئے ان کے لئے بخشش اور آبرو کی روزی ہے','So those who believe and do good will have forgiveness and an honourable provision','पस जिन लोगों ने ईमान कुबूल किया और अच्छे-अच्छे काम किए (आख़िरत में) उनके लिए बख्शिश है और बेहिश्त की बहुत उम्दा रोज़ी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,51,'Al-Hajj','وَٱلَّذِينَ سَعَوۡاْ فِيٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلۡجَحِيمِ','اور جن لوگوں نے ہماری آیتوں میں (اپنے زعم باطل میں) ہمیں عاجز کرنے کے لئے سعی کی، وہ اہل دوزخ ہیں','But those who strive to discredit Our revelations, they will be the residents of the Hellfire.”','और जिन लोगों ने हमारी आयतों (के झुठलाने में हमारे) आजिज़ करने के वास्ते कोशिश की यही लोग तो जहन्नुमी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,52,'Al-Hajj','وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولࣲ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمࣱ‏','اور ہم نے تم سے پہلے کوئی رسول اور نبی نہیں بھیجا مگر (اس کا یہ حال تھا کہ) جب وہ کوئی آرزو کرتا تھا تو شیطان اس کی آرزو میں (وسوسہ) ڈال دیتا تھا۔ تو جو (وسوسہ) شیطان ڈالتا ہے خدا اس کو دور کردیتا ہے۔ پھر خدا اپنی آیتوں کو مضبوط کردیتا ہے۔ اور خدا علم والا اور حکمت والا ہے','Whenever We sent a messenger or a prophet before you ˹O Prophet˺ and he recited ˹Our revelations˺, Satan would influence ˹people’s understanding of˺ his recitation. But ˹eventually˺ Allah would eliminate Satan’s influence. Then Allah would ˹firmly˺ establish His revelations. And Allah is All-Knowing, All-Wise','और (ऐ रसूल) हमने तो तुमसे पहले जब कभी कोई रसूल और नबी भेजा तो ये ज़रूर हुआ कि जिस वक्त उसने (तबलीग़े एहकाम की) आरज़ू की तो शैतान ने उसकी आरज़ू में (लोंगों को बहका कर) ख़लल डाल दिया फिर जो वस वसा शैतान डालता है खुदा उसे बेट देता है फिर अपने एहकाम को मज़बूत करता है और खुदा तो बड़ा वाक़िफकार दाना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,53,'Al-Hajj','لِّيَجۡعَلَ مَا يُلۡقِي ٱلشَّيۡطَٰنُ فِتۡنَةࣰ لِّلَّذِينَ فِي قُلُوبِهِم مَّرَضࣱ وَٱلۡقَاسِيَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّٰلِمِينَ لَفِي شِقَاقِۭ بَعِيدࣲ‏','غرض (اس سے) یہ ہے کہ جو (وسوسہ) شیطان ڈالتا ہے اس کو ان لوگوں کے لئے جن کے دلوں میں بیماری ہے اور جن کے دل سخت ہیں ذریعہ آزمائش ٹھہرائے۔ بےشک ظالم پرلے درجے کی مخالفت میں ہیں','All that so He may make Satan’s influence a trial for those ˹hypocrites˺ whose hearts are sick and those ˹disbelievers˺ whose hearts are hardened. Surely the wrongdoers are totally engrossed in opposition','और शैतान जो (वसवसा) डालता (भी) है तो इसलिए ताकि खुदा उसे उन लोगों के आज़माइश (का ज़रिया) क़रार दे जिनके दिलों में (कुफ्र का) मर्ज़ है और जिनके दिल सख्त हैं और बेशक (ये) ज़ालिम मुशरेकीन पल्ले दरजे की मुख़ालेफ़त में पड़े हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,54,'Al-Hajj','وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اور یہ بھی غرض ہے کہ جن لوگوں کو علم عطا ہوا ہے وہ جان لیں کہ وہ (یعنی وحی) تمہارے پروردگار کی طرف سے حق ہے تو وہ اس پر ایمان لائیں اور ان کے دل خدا کے آگے عاجزی کریں۔ اور جو لوگ ایمان لائے ہیں خدا ان کو سیدھے رستے کی طرف ہدایت کرتا ہے','˹This is˺ also so that those gifted with knowledge would know that this ˹revelation˺ is the truth from your Lord, so they have faith in it, and so their hearts would submit humbly to it. And Allah surely guides the believers to the Straight Path','और (इसलिए भी) ताकि जिन लोगों को (कुतूबे समावी का) इल्म अता हुआ है वह जान लें कि ये (वही) बेशक तुम्हारे परवरदिगार की तरफ से ठीक ठीक (नाज़िल) हुईहै फिर (ये ख्याल करके) इस पर वह लोग ईमान लाए फिर उनके दिल खुदा के सामने आजिज़ी करें और इसमें तो शक ही नहीं कि जिन लोगों ने ईमान कुबूल किया उनकी खुदा सीधी राह तक पहुँचा देता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,55,'Al-Hajj','وَلَا يَزَالُ ٱلَّذِينَ كَفَرُواْ فِي مِرۡيَةࣲ مِّنۡهُ حَتَّىٰ تَأۡتِيَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ يَأۡتِيَهُمۡ عَذَابُ يَوۡمٍ عَقِيمٍ','اور کافر لوگ ہمیشہ اس سے شک میں رہیں گے یہاں تک کہ قیامت ان پر ناگہاں آجائے یا ایک نامبارک دن کا عذاب ان پر واقع ہو','Yet the disbelievers will persist in doubt about this ˹revelation˺ until the Hour takes them by surprise, or the torment of a terminating Day comes to them','और जो लोग काफिर हो बैठे वह तो कुरान की तरफ से हमेशा शक ही में पड़े रहेंगे यहाँ तक कि क़यामत यकायक उनके सर पर आ मौजूद हो या (यूँ कहो कि) उनपर एक सख्त मनहूस दिन का अज़ाब नाज़िल हुआ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,56,'Al-Hajj','ٱلۡمُلۡكُ يَوۡمَئِذࣲ لِّلَّهِ يَحۡكُمُ بَيۡنَهُمۡۚ فَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فِي جَنَّٰتِ ٱلنَّعِيمِ','اس روز بادشاہی خدا ہی کی ہوگی۔ اور ان میں فیصلہ کردے گا تو جو لوگ ایمان لائے اور عمل نیک کرتے رہے وہ نعمت کے باغوں میں ہوں گے','All authority on that Day is for Allah ˹alone˺. He will judge between them. So those who believe and do good will be in the Gardens of Bliss','उस दिन की हुकूमत तो ख़ास खुदा ही की होगी वह लोगों (के बाहमी एख्तेलाफ) का फ़ैसला कर देगा तो जिन लोगों ने ईमान कुबूल किया और अच्छे काम किए हैं वह नेअमतों के (भरे) हुए बाग़ात (बेहश्त) में रहेंगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,57,'Al-Hajj','وَٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِـَٔايَٰتِنَا فَأُوْلَٰٓئِكَ لَهُمۡ عَذَابࣱ مُّهِينࣱ‏','اور جو کافر ہوئے اور ہماری آیتوں کو جھٹلاتے رہے ان کے لئے ذلیل کرنے والا عذاب ہوگا','But those who disbelieve and deny Our revelations, it is they who will suffer a humiliating punishment','और जिन लोगों ने कुफ्र एख्तियार किया और हमारी आयतों को झुठलाया तो यही वह (कम्बख्त) लोग हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,58,'Al-Hajj','وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنࣰ اۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ','اور جن لوگوں نے خدا کی راہ میں ہجرت کی پھر مارے گئے یا مر گئے۔ ان کو خدا اچھی روزی دے گا۔ اور بےشک خدا سب سے بہتر رزق دینے والا ہے','As for those who emigrate in the cause of Allah and then are martyred or die, Allah will indeed grant them a good provision. Surely Allah is the Best Provider','जिनके लिए ज़लील करने वाला अज़ाब है जिन लोगों ने खुदा की राह में अपने देस छोडे फ़िर शहीद किए गए या (आप अपनी मौत से) मर गए खुदा उन्हें (आख़िरत में) ज़रूर उम्दा रोज़ी अता फ़रमाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,59,'Al-Hajj','لَيُدۡخِلَنَّهُم مُّدۡخَلࣰ ا يَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِيمٌ حَلِيمࣱ‏','وہ ان کو ایسے مقام میں داخل کرے گا جسے وہ پسند کریں گے۔ اور خدا تو جاننے والا (اور) بردبار ہے','He will certainly admit them into a place they will be pleased with. For Allah is truly All-Knowing, Most Forbearing','और बेशक तमाम रोज़ी देने वालों में खुदा ही सबसे बेहतर है वह उन्हें ज़रूर ऐसी जगह (बेहिश्त) पहुँचा देगा जिससे वह निहाल हो जाएँगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,60,'Al-Hajj','۞ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ‏','یہ (بات خدا کے ہاں ٹھہر چکی ہے) اور جو شخص (کسی کو) اتنی ہی ایذا دے جتنی ایذا اس کو دی گئی پھر اس شخص پر زیادتی کی جائے تو خدا اس کی مدد کرے گا۔ بےشک خدا معاف کرنے والا اور بخشنے والا ہے','That is so. And whoever retaliates in equivalence to the injury they have received, and then are wronged ˹again˺, Allah will certainly help them. Surely Allah is Ever-Pardoning, All-Forgiving','और खुदा तो बेशक बड़ा वाक़िफकार बुर्दवार है यही (ठीक) है और जो शख्स (अपने दुश्मन को) उतना ही सताए जितना ये उसके हाथों से सताया गया था उसके बाद फिर (दोबारा दुशमन की तरफ़ से) उस पर ज्यादती की जाए तो खुदा उस मज़लूम की ज़रूर मदद करेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,61,'Al-Hajj','ذَٰلِكَ بِأَنَّ ٱللَّهَ يُولِجُ ٱلَّيۡلَ فِي ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِي ٱلَّيۡلِ وَأَنَّ ٱللَّهَ سَمِيعُۢ بَصِيرࣱ‏','یہ اس لئے کہ خدا رات کو دن میں داخل کردیتا ہے اور دن کو رات میں داخل کرتا ہے۔ اور خدا تو سننے والا دیکھنے والا ہے','That is because Allah causes the night to merge into the day, and the day into the night. Indeed, Allah is All-Hearing, All-Seeing','बेशक खुदा बड़ा माफ करने वाला बख़शने वाला है ये (मदद) इस वजह से दी जाएगी कि खुदा (बड़ा क़ादिर है वही) तो रात को दिन में दाख़िल करता है और दिन को रात में दाख़िल करता है और इसमें भी शक नहीं कि खुदा सब कुछ जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,62,'Al-Hajj','ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ','یہ اس لئے کہ خدا ہی برحق ہے اور جس چیز کو (کافر) خدا کے سوا پکارتے ہیں وہ باطل ہے اور اس لئے خدا رفیع الشان اور بڑا ہے','That is because Allah ˹alone˺ is the Truth and what they invoke besides Him is falsehood, and Allah ˹alone˺ is truly the Most High, All-Great','(और) इस वजह से (भी) कि यक़ीनन खुदा ही बरहक़ है और उसके सिवा जिनको लोग (वक्ते मुसीबत) पुकारा करते हैं (सबके सब) बातिल हैं और (ये भी) यक़ीनी (है कि) खुदा ही (सबसे) बुलन्द मर्तबा बुर्जुग़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,63,'Al-Hajj','أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءࣰ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِيفٌ خَبِيرࣱ‏','کیا تم نہیں دیکھتے کہ خدا آسمان سے مینہ برساتا ہے تو زمین سرسبز ہوجاتی ہے۔ بےشک خدا باریک بین اور خبردار ہے','Do you not see that Allah sends down rain from the sky, then the earth becomes green? Surely Allah is Most Subtle, All-Aware','अरे क्या तूने इतना भी नहीं देखा कि खुदा ही आसमान से पानी बरसाता है तो ज़मीन सर सब्ज़ (व शादाब) हो जाती है बेशक खुदा (बन्दों के हाल पर) बड़ा मेहरबान वाक़िफ़कार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,64,'Al-Hajj','لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ','جو کچھ آسمانوں میں ہے اور جو کچھ زمین میں ہے اسی کا ہے۔ اور بےشک خدا بےنیاز اور قابل ستائش ہے۔','To Him belongs whatever is in the heavens and whatever is on the earth. Allah ˹alone˺ is truly the Self-Sufficient, Praiseworthy','जो कुछ आसमानों में है और जो कुछ ज़मीन में है (ग़रज़ सब कुछ) उसी का है और इसमें तो शक ही नहीं कि खुदा (सबसे) बेपरवाह (और) सज़ावार हम्द है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,65,'Al-Hajj','أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِي ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَيُمۡسِكُ ٱلسَّمَآءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦٓۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ‏','کیا تم نہیں دیکھتے کہ جتنی چیزیں زمین میں ہیں (سب) خدا نے تمہارے زیرفرمان کر رکھی ہیں اور کشتیاں (بھی) جو اسی کے حکم سے دریا میں چلتی ہیں۔ اور وہ آسمان کو تھامے رہتا ہے کہ زمین پر (نہ) گڑ پڑے مگر اس کے حکم سے۔ بےشک خدا لوگوں پر نہایت شفقت کرنے والا مہربان ہے','Do you not see that Allah has subjected to you whatever is in the earth as well as the ships ˹that˺ sail through the sea by His command? He keeps the sky from falling down on the earth except by His permission. Surely Allah is Ever Gracious and Most Merciful to humanity','क्या तूने उस पर भी नज़र न डाली कि जो कुछ रूए ज़मीन में है सबको खुदा ही ने तुम्हारे क़ाबू में कर दिया है और कश्ती को (भी) जो उसके हुक्म से दरिया में चलती है और वही तो आसमान को रोके हुए है कि ज़मीन पर न गिर पड़े मगर (जब) उसका हुक्म होगा (तो गिर पडेग़ा) इसमें शक नहीं कि खुदा लोगों पर बड़ा मेहरबान व रहमवाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,66,'Al-Hajj','وَهُوَ ٱلَّذِيٓ أَحۡيَاكُمۡ ثُمَّ يُمِيتُكُمۡ ثُمَّ يُحۡيِيكُمۡۗ إِنَّ ٱلۡإِنسَٰنَ لَكَفُورࣱ‏','اور وہی تو ہے جس نے تم کو حیات بخشی۔ پھر تم کو مارتا ہے۔ پھر تمہیں زندہ بھی کرے گا۔ اور انسان تو بڑا ناشکر ہے','And He is the One Who gave you life, then will cause you to die, and then will bring you back to life. ˹But˺ surely humankind is ever ungrateful','और वही तो क़ादिर मुत्तलिक़ है जिसने तुमको (पहली बार माँ के पेट में) जिला उठाया फिर वही तुमको मार डालेगा फिर वही तुमको दोबारा ज़िन्दगी देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,67,'Al-Hajj','لِّكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا يُنَٰزِعُنَّكَ فِي ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدࣰ ى مُّسۡتَقِيمࣲ‏','ہم نے ہر ایک اُمت کے لئے ایک شریعت مقرر کردی ہے جس پر وہ چلتے ہیں تو یہ لوگ تم سے اس امر میں جھگڑا نہ کریں اور تم (لوگوں کو) اپنے پروردگار کی طرف بلاتے رہو۔ بےشک تم سیدھے رستے پر ہو','For every community We appointed a code of life to follow. So do not let them dispute with you ˹O Prophet˺ in this matter. And invite ˹all˺ to your Lord, for you are truly on the Right Guidance','इसमें शक नहीं कि इन्सान बड़ा ही नाशुक्रा है (ऐ रसूल) हमने हर उम्मत के वास्ते एक तरीक़ा मुक़र्रर कर दिया कि वह इस पर चलते हैं फिर तो उन्हें इस दीन (इस्लाम) में तुम से झगड़ा न करना चाहिए और तुम (लोगों को) अपने परवरदिगार की तरफ बुलाए जाओ');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,68,'Al-Hajj','وَإِن جَٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ','اور اگر یہ تم سے جھگڑا کریں تو کہہ دو کہ جو عمل تم کرتے ہو خدا ان سے خوب واقف ہے','But if they argue with you, then say, “Allah knows best what you do.”','बेशक तुम सीधे रास्ते पर हो और अगर (इस पर भी) लोग तुमसे झगड़ा करें तो तुक कह दो कि जो कुछ तुम कर रहे हो खुदा उससे खूब वाक़िफ़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,69,'Al-Hajj','ٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','جن باتوں میں تم اختلاف کرتے ہو خدا تم میں قیامت کے روز ان کا فیصلہ کردے گا','Allah will judge between you ˹all˺ on Judgment Day regarding your differences','जिन बातों में तुम बाहम झगड़ा करते थे क़यामत के दिन ख़ुदा तुम लोगों के दरमियान (ठीक) फ़ैसला कर देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,70,'Al-Hajj','أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِنَّ ذَٰلِكَ فِي كِتَٰبٍۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرࣱ‏','کیا تم نہیں جانتے کہ جو کچھ آسمان اور زمین میں ہے خدا اس کو جانتا ہے۔ یہ (سب کچھ) کتاب میں (لکھا ہوا) ہے۔ بےشک یہ سب خدا کو آسان ہے','Do you not know that Allah ˹fully˺ knows whatever is in the heavens and the earth? Surely it is all ˹written˺ in a Record. That is certainly easy for Allah','(ऐ रसूल) क्या तुम नहीं जानते कि जो कुछ आसमान और ज़मीन में है खुदा यक़ीनन जानता है उसमें तो शक नहीं कि ये सब (बातें) किताब (लौहे महफूज़) में (लिखी हुईमौजूद) हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,71,'Al-Hajj','وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنࣰ ا وَمَا لَيۡسَ لَهُم بِهِۦ عِلۡمࣱۗ وَمَا لِلظَّٰلِمِينَ مِن نَّصِيرࣲ‏','اور (یہ لوگ) خدا کے سوا ایسی چیزوں کی عبادت کرتے ہیں جن کی اس نے کوئی سند نازل نہیں فرمائی اور نہ ان کے پاس اس کی کوئی دلیل ہے۔ اور ظالموں کا کوئی بھی مددگار نہیں ہوگا','Yet they worship besides Allah that for which He has sent down no authority, and of which they have no knowledge. The wrongdoers will have no helper','बेशक ये (सब कुछ) खुदा पर आसान है और ये लोग खुदा को छोड़कर उन लोगों की इबादत करते हैं जिनके लिए न तो ख़ुदा ही ने कोई सनद नाज़िल की है और न उस (के हक़ होने) का खुद उन्हें इल्म है और क़यामत में तो ज़ालिमों का कोई मददगार भी नहीं होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,72,'Al-Hajj','وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتࣲ تَعۡرِفُ فِي وُجُوهِ ٱلَّذِينَ كَفَرُواْ ٱلۡمُنكَرَۖ يَكَادُونَ يَسۡطُونَ بِٱلَّذِينَ يَتۡلُونَ عَلَيۡهِمۡ ءَايَٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرࣲّ مِّن ذَٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِينَ كَفَرُواْۖ وَبِئۡسَ ٱلۡمَصِيرُ','اور جب ان کو ہماری آیتیں پڑھ کر سنائی جاتی تو (ان کی شکل بگڑ جاتی ہے اور) تم ان کے چہروں میں صاف طور پر ناخوشی (کے آثار) دیکھتے ہو۔ قریب ہوتے ہیں کہ جو لوگ ان کو ہماری آیتیں پڑھ کر سناتے ہیں ان پر حملہ کردیں۔ کہہ دو کہ میں تم کو اس سے بھی بری چیز بتاؤں؟ وہ دوزخ کی آگ ہے۔ جس کا خدا نے کافروں سے وعدہ کیا ہے۔ اور وہ برا ٹھکانا ہے','Whenever Our clear revelations are recited to them, you ˹O Prophet˺ recognize rage on the faces of the disbelievers, as if they are going to snap at those who recite Our revelations to them. Say, “Shall I inform you of something far more enraging than that? ˹It is˺ the Fire with which Allah has threatened those who disbelieve. What an evil destination!”','और (ऐ रसूल) जब हमारी वाज़ेए व रौशन आयतें उनके सामने पढ़ कर सुनाई जाती हैं तो तुम (उन) काफिरों के चेहरों पर नाखुशी के (आसार) देखते हो (यहाँ तक कि) क़रीब होता है कि जो लोग उनको हमारी आयातें पढ़कर सुनाते हैं उन पर ये लोग हमला कर बैठे (ऐ रसूल) तुम कह दो (कि) तो क्या मैं तुम्हें इससे भी कहीं बदतर चीज़ बता दूँ (अच्छा) तो सुन लो वह जहन्नुम है जिसमें झोंकने का वायदा खुदा ने काफ़िरों से किया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,73,'Al-Hajj','يَٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُواْ لَهُۥٓۚ إِنَّ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن يَخۡلُقُواْ ذُبَابࣰ ا وَلَوِ ٱجۡتَمَعُواْ لَهُۥۖ وَإِن يَسۡلُبۡهُمُ ٱلذُّبَابُ شَيۡـࣰٔ ا لَّا يَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ','لوگو! ایک مثال بیان کی جاتی ہے اسے غور سے سنو۔ کہ جن لوگوں کو تم خدا کے سوا پکارتے ہو وہ ایک مکھی بھی نہیں بنا سکتے اگرچہ اس کے لئے سب مجتمع ہوجائیں۔ اور اگر ان سے مکھی کوئی چیز لے جائے تو اسے اس سے چھڑا نہیں سکتے۔ طالب اور مطلوب (یعنی عابد اور معبود دونوں) گئے گزرے ہیں','O humanity! A lesson is set forth, so listen to it ˹carefully˺: those ˹idols˺ you invoke besides Allah can never create ˹so much as˺ a fly, even if they ˹all˺ were to come together for that. And if a fly were to snatch anything away from them, they cannot ˹even˺ retrieve it from the fly. How powerless are those who invoke and those invoked','और वह क्या बुरा ठिकाना है लोगों एक मसल बयान की जाती है तो उसे कान लगा के सुनो कि खुदा को छोड़कर जिन लोगों को तुम पुकारते हो वह लोग अगरचे सब के सब इस काम के लिए इकट्ठे भी हो जाएँ तो भी एक मक्खी तक पैदा नहीं कर सकते और कहीं मक्खी कुछ उनसे छीन ले जाए तो उससे उसको छुड़ा नहीं सकते (अजब लुत्फ है) कि माँगने वाला (आबिद) और जिससे माँग लिया (माबूद) दोनों कमज़ोर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,74,'Al-Hajj','مَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ','ان لوگوں نے خدا کی قدر جیسی کرنی چاہیئے تھی نہیں کی۔ کچھ شک نہیں کہ خدا زبردست اور غالب ہے','They have not shown Allah the reverence He deserves. Surely Allah is All-Powerful, Almighty','खुदा की जैसे क़द्र करनी चाहिए उन लोगों ने न की इसमें शक नहीं कि खुदा तो बड़ा ज़बरदस्त ग़ालिब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,75,'Al-Hajj','ٱللَّهُ يَصۡطَفِي مِنَ ٱلۡمَلَٰٓئِكَةِ رُسُلࣰ ا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرࣱ‏','خدا فرشتوں میں سے پیغام پہنچانے والے منتخب کرلیتا ہے اور انسانوں میں سے بھی۔ بےشک خدا سننے والا (اور) دیکھنے والا ہے','Allah selects messengers from both angels and people, for Allah is truly All-Hearing, All-Seeing','खुदा फरिश्तों में से बाज़ को अपने एहकाम पहुँचाने के लिए मुन्तख़िब कर लेता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,76,'Al-Hajj','يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ','جو ان کے آگے ہے اور جن ان کے پیچھے ہے وہ اس سے واقف ہے۔ اور سب کاموں کا رجوع خدا ہی کی طرف ہے','He knows what is ahead of them and what is behind them. And to Allah ˹all˺ matters will be returned ˹for judgment˺','और (इसी तरह) आदमियों में से भी बेशक खुदा (सबकी) सुनता देखता है जो कुछ उनके सामने है और जो कुछ उनके पीछे (हो चुका है) (खुदा सब कुछ) जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (22,77,'Al-Hajj','يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱرۡكَعُواْ وَٱسۡجُدُواْۤ وَٱعۡبُدُواْ رَبَّكُمۡ وَٱفۡعَلُواْ ٱلۡخَيۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ۩','مومنو! رکوع کرتے اور سجدے کرتے اور اپنے پروردگار کی عبادت کرتے رہو اور نیک کام کرو تاکہ فلاح پاؤ','O believers! Bow down, prostrate yourselves, worship your Lord, and do ˹what is˺ good so that you may be successful','और तमाम उमूर की रूजू खुदा ही की तरफ होती है ऐ ईमानवालों रूकू करो और सजदे करो और अपने परवरदिगार की इबादत करो और नेकी करो');
